    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo''s indemnification obligations shall apply to any and all third-party claims, demands, actions, suits or proceedings arising out of or relating to the development, production, post-production, marketing, distribution, exhibition or other exploitation of the Program or any Materials.', ARRAY['indemnification','third-party claims','demands','actions','suits','proceedings','development','production','post-production','marketing','distribution','exhibition','exploitation','Program','Materials']::text[], '{"doc": "PSA_Principal_Terms", "section": "Indemnification", "note": "Full lifecycle coverage", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Covers full Program lifecycle from development through exploitation. Essential scope for comprehensive protection against claims at any stage."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Indemnified claims include any claim by a third party: (a) alleging infringement of intellectual property rights; (b) alleging defamation, libel, slander, or invasion of privacy; (c) alleging breach of contract or tortious interference; (d) arising from workplace injuries or safety violations during production; or (e) otherwise arising from or relating to the Program or ProdCo''s performance hereunder.', ARRAY['Indemnified claims','third party','infringement','intellectual property','defamation','libel','slander','privacy','breach of contract','tortious interference','workplace injuries','safety violations','production','Program','performance']::text[], '{"doc": "PSA_Principal_Terms", "section": "Indemnification", "note": "Enumerated claim types with catch-all", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Enumerates specific claim categories while including catch-all. Covers content claims, employment/safety claims, and contract claims. Comprehensive."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo shall indemnify against all Losses arising from third-party claims relating to: (i) the Program, including all elements and Materials; (ii) ProdCo''s acts or omissions in connection with this Agreement; (iii) any actual or alleged breach by ProdCo; (iv) the production process, including any on-set incidents; and (v) ProdCo''s personnel, contractors, agents and representatives.', ARRAY['Losses','third-party claims','Program','elements','Materials','acts','omissions','breach','production process','on-set incidents','personnel','contractors','agents','representatives']::text[], '{"doc": "PSA_Principal_Terms", "section": "Indemnification", "note": "Personnel and on-set coverage", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Includes on-set incidents and ProdCo personnel coverage, addressing common production liability scenarios. Comprehensive scope."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'The scope of ProdCo''s indemnification extends to any claim arising from the conception, development, writing, production, post-production or delivery of the Program, and to any claim arising from Amazon''s subsequent exploitation, distribution, marketing, advertising, promotion or licensing of the Program worldwide in perpetuity.', ARRAY['scope','indemnification','conception','development','writing','production','post-production','delivery','Amazon''s exploitation','distribution','marketing','advertising','promotion','licensing','worldwide','perpetuity']::text[], '{"doc": "PSA_Principal_Terms", "section": "Indemnification", "note": "Perpetual exploitation coverage", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Extends indemnity to claims arising from perpetual worldwide exploitation. Essential for long-term content exploitation protection."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Third-party claims covered by this indemnity include claims by: (a) cast, crew, or other production personnel; (b) rights holders in underlying works, music, or other content; (c) subjects of documentary content or their representatives; (d) vendors, suppliers, or production services providers; and (e) any other third party affected by the Program or production activities.', ARRAY['third-party claims','cast','crew','production personnel','rights holders','underlying works','music','subjects','documentary','representatives','vendors','suppliers','production services','affected','production activities']::text[], '{"doc": "PSA_Principal_Terms", "section": "Indemnification", "note": "Third-party claimant categories", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Enumerates categories of potential third-party claimants, providing clarity on coverage scope while maintaining comprehensive catch-all."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo''s indemnity covers all third-party claims, whether based in contract, tort, statute, or otherwise, and regardless of whether such claims arise before, during, or after the term of this Agreement, so long as the underlying acts or omissions occurred during the term or relate to the Program.', ARRAY['third-party claims','contract','tort','statute','otherwise','before','during','after','term','underlying acts','omissions','during term','relate to','Program']::text[], '{"doc": "PSA_Principal_Terms", "section": "Indemnification", "note": "Legal basis and timing coverage", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Covers all legal theories and claims arising at any time if underlying conduct was during term. Essential for latent claim scenarios."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo shall indemnify against claims arising from the Program as delivered, as well as claims arising from any derivative works, sequels, prequels, remakes, spinoffs, or other adaptations of the Program that incorporate elements created by ProdCo, regardless of whether Amazon commissions such works from ProdCo or third parties.', ARRAY['claims','Program as delivered','derivative works','sequels','prequels','remakes','spinoffs','adaptations','elements created by ProdCo','commissions','third parties']::text[], '{"doc": "PSA_Principal_Terms", "section": "Indemnification", "note": "Derivative works coverage", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Extends indemnity to derivative works incorporating ProdCo elements. Important for franchise exploitation protection."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo''s indemnity covers third-party claims arising from development and production of the Program. Claims arising solely from Amazon''s post-delivery modifications or additions to the Program shall not be covered, except to the extent such claims also relate to ProdCo-created elements.', ARRAY['third-party claims','development','production','Program','Amazon''s post-delivery','modifications','additions','not covered','except','relate to','ProdCo-created elements']::text[], '{"doc": "Counterparty_Markup", "section": "Indemnification", "note": "Post-delivery modification carveout", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Carveout for claims arising solely from Amazon post-delivery changes is reasonable allocation. Exception for ProdCo elements in modified content preserves appropriate coverage."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo''s indemnification applies to third-party claims relating to the Program. If a claim relates to both ProdCo-created content and Amazon-supplied materials, ProdCo''s indemnification shall apply only to the portion of Losses attributable to ProdCo-created content, as reasonably determined by Amazon.', ARRAY['third-party claims','Program','ProdCo-created content','Amazon-supplied materials','portion of Losses','attributable','reasonably determined','Amazon']::text[], '{"doc": "Counterparty_Markup", "section": "Indemnification", "note": "Allocation for mixed-source claims", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Allocation for mixed-source claims is reasonable where Amazon has contributed materials. Amazon''s reasonable determination authority preserves control."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo''s indemnity covers claims arising from production activities. For claims involving production accidents or injuries, ProdCo''s indemnity shall apply unless the accident resulted directly from Amazon''s written direction to perform a specific action that caused the injury.', ARRAY['claims','production activities','production accidents','injuries','indemnity applies','unless','directly from','Amazon''s written direction','specific action','caused injury']::text[], '{"doc": "Counterparty_Markup", "section": "Indemnification", "note": "Amazon-directed action exception", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Narrow exception for injuries from Amazon-directed specific actions is reasonable if written direction requirement is clear. Most production decisions are ProdCo''s responsibility."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Third-party claims covered include development and production claims. ProdCo shall provide Amazon with periodic reports of any claims, demands, or threats received, and Amazon may require additional insurance coverage if Amazon determines that claim exposure warrants enhanced protection.', ARRAY['third-party claims','development','production','periodic reports','claims','demands','threats','additional insurance','Amazon determines','claim exposure','enhanced protection']::text[], '{"doc": "PSA_Fallbacks", "section": "Indemnification", "note": "Claims reporting with insurance adjustment", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Claims reporting and Amazon''s right to require additional insurance are protective additions that don''t limit indemnity scope."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo''s indemnity covers claims relating to the Program. The parties acknowledge that certain claims may be covered by production insurance, and ProdCo shall ensure all production insurance names Amazon as additional insured with primary and non-contributory coverage.', ARRAY['claims','Program','production insurance','names Amazon','additional insured','primary','non-contributory coverage']::text[], '{"doc": "Counterparty_Markup", "section": "Indemnification", "note": "Production insurance additional insured", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Additional insured status with primary/non-contributory language is standard protection that complements indemnification obligations."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo''s indemnification extends to third-party claims. If any claim involves allegations of criminal conduct or regulatory violations, ProdCo shall cooperate fully with any investigation and shall not take any action that could prejudice Amazon''s legal position or reputation.', ARRAY['third-party claims','criminal conduct','regulatory violations','cooperate','investigation','not take action','prejudice','Amazon''s legal position','reputation']::text[], '{"doc": "Counterparty_Markup", "section": "Indemnification", "note": "Criminal/regulatory claim handling", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Cooperation and non-prejudice requirements for criminal/regulatory claims are appropriate protections for serious matters."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo''s indemnification shall apply only to third-party claims that have been finally adjudicated to arise from ProdCo''s production activities. Claims that are settled, dismissed, or voluntarily abandoned shall not be covered.', ARRAY['only','third-party claims','finally adjudicated','production activities','settled','dismissed','voluntarily abandoned','not covered']::text[], '{"doc": "Counterparty_Markup", "section": "Indemnification", "note": "Final adjudication requirement", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Final adjudication requirement excludes settlements (vast majority of claims). Excluding dismissed claims also removes coverage for defense costs of non-meritorious claims."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo''s indemnification covers claims arising from production only. Claims arising from Amazon''s marketing, distribution, exploitation, or other post-delivery activities shall be Amazon''s sole responsibility and shall not be covered by ProdCo''s indemnity.', ARRAY['claims','production only','Amazon''s marketing','distribution','exploitation','post-delivery','Amazon''s sole responsibility','not covered']::text[], '{"doc": "Counterparty_Markup", "section": "Indemnification", "note": "Production-only scope", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Limiting indemnity to production claims only excludes claims arising from content during exploitation\u2014where most claims actually arise. Scope must cover full exploitation lifecycle."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo''s indemnity covers U.S. third-party claims only. Claims arising in jurisdictions outside the United States, including European Union, United Kingdom, and other international territories, shall not be covered by ProdCo''s indemnification obligations.', ARRAY['U.S. third-party claims','only','jurisdictions','outside United States','EU','UK','international','not covered']::text[], '{"doc": "Counterparty_Markup", "section": "Indemnification", "note": "U.S.-only coverage", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Limiting indemnity to U.S. claims only leaves Amazon exposed in all international territories. Global exploitation requires worldwide indemnification coverage."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo''s indemnification applies to third-party claims. However, claims by guild or union members, collective bargaining grievances, and labor-related claims shall be excluded from ProdCo''s indemnity and shall be handled through applicable labor relations processes.', ARRAY['third-party claims','guild','union members','collective bargaining grievances','labor-related claims','excluded','labor relations processes']::text[], '{"doc": "Counterparty_Markup", "section": "Indemnification", "note": "Guild/union claims excluded", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Excluding guild/union and labor claims removes a significant category of production-related claims from coverage. ProdCo manages production personnel and should indemnify for related claims."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo''s indemnity covers claims by unrelated third parties. Claims by ProdCo''s employees, contractors, vendors, or other parties in contractual privity with ProdCo shall not be covered, as such claims are matters between ProdCo and such parties.', ARRAY['claims','unrelated third parties','ProdCo''s employees','contractors','vendors','contractual privity','not covered','matters between','ProdCo']::text[], '{"doc": "Counterparty_Markup", "section": "Indemnification", "note": "Privity carveout", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Excluding claims by ProdCo''s personnel and vendors removes many common claim scenarios. If such parties sue Amazon, ProdCo should indemnify regardless of their relationship with ProdCo."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo''s indemnification covers third-party claims asserted during production and for one (1) year following delivery. Claims asserted more than one year after delivery shall not be subject to ProdCo''s indemnification obligations.', ARRAY['third-party claims','during production','one year','following delivery','more than one year','not subject','indemnification']::text[], '{"doc": "Counterparty_Markup", "section": "Indemnification", "note": "One-year post-delivery limit", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "One-year post-delivery limitation is grossly inadequate given statutes of limitations for infringement and defamation claims, which can run for years. Indemnity must survive indefinitely."}'::jsonb)
    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo''s indemnification obligations shall be triggered by: (a) any breach or alleged breach of any representation, warranty, covenant or obligation of ProdCo under this Agreement; (b) any negligent or wrongful act or omission by ProdCo or its personnel; (c) any willful misconduct by ProdCo; or (d) any third-party claim arising from or relating to the Program or Materials.', ARRAY['indemnification','triggered','breach','alleged breach','representation','warranty','covenant','obligation','negligent','wrongful act','omission','personnel','willful misconduct','third-party claim','Program','Materials']::text[], '{"doc": "PSA_Principal_Terms", "section": "Indemnification", "note": "Comprehensive trigger enumeration", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Comprehensive enumeration of triggers covering breach, negligence, willful misconduct, and third-party claims. ''Alleged breach'' trigger is included which Amazon typically prefers to delete, but comprehensive coverage is still achieved."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Indemnification shall apply to Losses arising from: (i) breach of ProdCo''s representations and warranties; (ii) breach of ProdCo''s covenants and obligations; (iii) ProdCo''s negligence or other tortious conduct; (iv) ProdCo''s violation of applicable law; or (v) any act or omission of ProdCo''s employees, contractors, agents or representatives.', ARRAY['Losses','breach','representations','warranties','covenants','obligations','negligence','tortious conduct','violation','applicable law','act','omission','employees','contractors','agents','representatives']::text[], '{"doc": "PSA_Principal_Terms", "section": "Indemnification", "note": "Personnel conduct included", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Includes personnel conduct as explicit trigger. Legal violation trigger ensures compliance-related claims are covered. Comprehensive."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo shall indemnify against Losses arising from any breach by ProdCo of this Agreement, including breach of any representation, warranty, covenant, obligation or undertaking. For the avoidance of doubt, indemnification shall apply regardless of whether such breach is negligent, intentional, or strict liability.', ARRAY['Losses','breach','representation','warranty','covenant','obligation','undertaking','regardless','negligent','intentional','strict liability']::text[], '{"doc": "PSA_Principal_Terms", "section": "Indemnification", "note": "All liability standards covered", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Clarifies that indemnity applies regardless of liability standard (negligent, intentional, or strict). Prevents arguments about mens rea requirements."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Indemnification triggers include: (a) breach of representations regarding originality, non-infringement, and chain of title; (b) breach of representations regarding compliance with laws; (c) breach of confidentiality obligations; (d) negligence in production operations; (e) willful misconduct; and (f) any other breach of this Agreement.', ARRAY['triggers','breach','representations','originality','non-infringement','chain of title','compliance','laws','confidentiality','negligence','production operations','willful misconduct','other breach']::text[], '{"doc": "PSA_Principal_Terms", "section": "Indemnification", "note": "Specific representation breach triggers", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Enumerates specific representation categories that trigger indemnity while including catch-all for other breaches. Provides clarity without limiting scope."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo''s indemnification is triggered by any third-party claim based upon facts that, if true, would constitute a breach by ProdCo of any representation, warranty or obligation hereunder, or would constitute negligent or wrongful conduct by ProdCo. ProdCo''s indemnification obligation shall apply regardless of the ultimate merit of such claim.', ARRAY['triggered','third-party claim','based upon facts','if true','constitute breach','representation','warranty','obligation','negligent','wrongful conduct','regardless','ultimate merit']::text[], '{"doc": "PSA_Principal_Terms", "section": "Indemnification", "note": "Merit-independent trigger", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "''Regardless of ultimate merit'' ensures indemnification for defense of non-meritorious claims. Claims trigger indemnity based on allegations, not outcomes."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Indemnification is triggered by any breach of this Agreement by ProdCo, whether or not such breach is alleged, discovered, or claimed during the term. The triggering breach need not be material; any breach, regardless of materiality, shall give rise to indemnification for related Losses.', ARRAY['triggered','breach','alleged','discovered','claimed','during term','need not be material','any breach','regardless of materiality','Losses']::text[], '{"doc": "PSA_Principal_Terms", "section": "Indemnification", "note": "Non-material breach coverage", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Explicitly covers non-material breaches, preventing ProdCo from arguing that indemnity only applies to material breaches. Important for comprehensive coverage."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo''s indemnification applies to Losses from: breach of representations and warranties; breach of covenants; negligent acts or omissions; willful misconduct; and fraud. ProdCo''s indemnification for fraud and willful misconduct shall not be subject to any limitation or cap.', ARRAY['Losses','breach','representations','warranties','covenants','negligent','acts','omissions','willful misconduct','fraud','not subject to','limitation','cap']::text[], '{"doc": "PSA_Principal_Terms", "section": "Indemnification", "note": "Fraud/willful misconduct uncapped", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Explicitly makes fraud and willful misconduct indemnity uncapped, which is important if any caps are negotiated elsewhere (which Amazon typically resists)."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Indemnification is triggered by breach of representations and warranties or negligence. ProdCo''s indemnification for breach of operational covenants (e.g., delivery schedules, format requirements) shall be limited to direct damages and shall not extend to consequential or reputational losses.', ARRAY['triggered','breach','representations','warranties','negligence','operational covenants','delivery schedules','format requirements','limited','direct damages','not extend','consequential','reputational']::text[], '{"doc": "Counterparty_Markup", "section": "Indemnification", "note": "Operational covenant limitation", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Limiting operational covenant breaches to direct damages may be reasonable for truly administrative matters. Legal should confirm content-related covenants are not included in this limitation."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Indemnification triggers include breach and negligence. For claims involving alleged defamation or invasion of privacy, ProdCo''s indemnification shall apply if ProdCo''s standard script clearance procedures were not followed or if clearance counsel''s recommendations were not implemented.', ARRAY['triggers','breach','negligence','defamation','invasion of privacy','indemnification','script clearance procedures','not followed','clearance counsel','recommendations','not implemented']::text[], '{"doc": "Counterparty_Markup", "section": "Indemnification", "note": "Clearance procedure linkage", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Linking defamation/privacy indemnity to clearance procedure compliance is reasonable if procedures are properly defined. Doesn''t eliminate indemnity, just clarifies trigger."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Indemnification applies to breach, negligence, and willful misconduct. If a claim involves both ProdCo triggers and Amazon triggers (e.g., Amazon-requested content changes), ProdCo''s indemnification shall apply on a proportionate basis reflecting relative fault as reasonably determined by Amazon.', ARRAY['breach','negligence','willful misconduct','ProdCo triggers','Amazon triggers','requested content changes','proportionate basis','relative fault','reasonably determined','Amazon']::text[], '{"doc": "Counterparty_Markup", "section": "Indemnification", "note": "Proportionate allocation for mixed claims", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Proportionate allocation for mixed-fault claims with Amazon''s reasonable determination authority is fair approach that preserves coverage for ProdCo''s portion."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo''s indemnification is triggered by breach or negligence. If Amazon provides ProdCo with notice of a claim and ProdCo disputes whether the claim involves a trigger event, the parties shall consult in good faith; Amazon''s reasonable determination shall be final for purposes of defense obligations pending resolution.', ARRAY['triggered','breach','negligence','notice of claim','ProdCo disputes','trigger event','consult','good faith','Amazon''s reasonable determination','final','defense obligations','pending resolution']::text[], '{"doc": "Counterparty_Markup", "section": "Indemnification", "note": "Dispute mechanism for trigger determination", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Consultation with Amazon''s interim determination authority allows defense to proceed during trigger disputes. Doesn''t eliminate indemnity, just provides process."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Indemnification triggers include breach, negligence, and willful misconduct by ProdCo. For the avoidance of doubt, ordinary business disagreements, good faith creative disputes, and reasonable interpretive differences shall not constitute ''negligence'' or ''breach'' for indemnification purposes.', ARRAY['triggers','breach','negligence','willful misconduct','ordinary business disagreements','good faith creative disputes','reasonable interpretive differences','not constitute','indemnification purposes']::text[], '{"doc": "Counterparty_Markup", "section": "Indemnification", "note": "Business dispute carveout", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Carveout for ordinary business/creative disputes is reasonable to prevent indemnity being invoked for routine disagreements. Substantive breaches remain covered."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Indemnification is triggered by breach of any representation or warranty. With respect to representations made ''to ProdCo''s knowledge'' (if any), a breach shall be deemed to occur only if ProdCo had actual knowledge of the relevant facts at the time of making the representation and failed to disclose them.', ARRAY['triggered','breach','representation','warranty','to ProdCo''s knowledge','deemed','actual knowledge','relevant facts','time of making','failed to disclose']::text[], '{"doc": "Counterparty_Markup", "section": "Indemnification", "note": "Knowledge qualifier trigger clarification", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "If any knowledge-qualified reps exist (which Amazon generally resists), this clarifies trigger mechanism. Should only apply to explicitly knowledge-qualified reps."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo''s indemnification is triggered only by ProdCo''s gross negligence or willful misconduct. Ordinary negligence, inadvertent errors, and unintentional breaches shall not trigger indemnification obligations.', ARRAY['triggered','only','gross negligence','willful misconduct','ordinary negligence','inadvertent errors','unintentional breaches','not trigger']::text[], '{"doc": "Counterparty_Markup", "section": "Indemnification", "note": "Gross negligence/willful misconduct only", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Limiting triggers to gross negligence/willful misconduct excludes vast majority of claims. Indemnification must cover all breaches and ordinary negligence."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Indemnification is triggered only by material breach of representations and warranties. Non-material breaches, technical violations, and breaches that do not result in actual third-party claims shall not trigger indemnification.', ARRAY['triggered','only','material breach','representations','warranties','non-material','technical violations','not result','actual third-party claims','not trigger']::text[], '{"doc": "Counterparty_Markup", "section": "Indemnification", "note": "Material breach only", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Materiality requirement excludes many legitimate claims. Requiring ''actual third-party claims'' would also exclude first-party losses. Both limitations are unacceptable."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo''s indemnification is triggered by breach of representations and warranties, but only to the extent Amazon has suffered actual, documented monetary losses that exceed $50,000 per claim or $250,000 in the aggregate.', ARRAY['triggered','breach','representations','warranties','only','actual','documented','monetary losses','exceed','$50,000','per claim','$250,000','aggregate']::text[], '{"doc": "Counterparty_Markup", "section": "Indemnification", "note": "Dollar thresholds for trigger", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Dollar thresholds for trigger create gap in coverage for smaller claims and require Amazon to absorb first-dollar losses. Indemnity must be first-dollar."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Indemnification triggers include breach and negligence, but only if Amazon provides ProdCo with notice of the claim within thirty (30) days of Amazon''s receipt of such claim. Late notice shall extinguish ProdCo''s indemnification obligations entirely.', ARRAY['triggers','breach','negligence','only if','notice','thirty days','receipt of claim','late notice','extinguish','indemnification','entirely']::text[], '{"doc": "Counterparty_Markup", "section": "Indemnification", "note": "Strict notice deadline with extinguishment", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Complete extinguishment for late notice is grossly disproportionate. Notice delay should only affect indemnity if ProdCo is actually prejudiced, and only to the extent of such prejudice."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo''s indemnification is triggered by breach of representations and warranties. Indemnification shall not be triggered by breach of covenants, operational obligations, or delivery requirements, as such matters are addressed through other Agreement remedies.', ARRAY['triggered','breach','representations','warranties','not triggered','covenants','operational obligations','delivery requirements','other Agreement remedies']::text[], '{"doc": "Counterparty_Markup", "section": "Indemnification", "note": "Covenant breaches excluded", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Excluding covenant breaches from indemnification triggers creates significant gap. Covenants (e.g., compliance, confidentiality) can generate third-party claims that must be indemnified."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Indemnification is triggered by breach established through final, non-appealable judgment of a court of competent jurisdiction. Settlements, arbitration awards, and administrative determinations shall not constitute ''breach'' for purposes of triggering indemnification.', ARRAY['triggered','breach','final','non-appealable judgment','court','competent jurisdiction','settlements','arbitration awards','administrative determinations','not constitute','breach']::text[], '{"doc": "Counterparty_Markup", "section": "Indemnification", "note": "Court judgment required", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Requiring court judgment to trigger indemnity excludes virtually all claims (most are settled). Administrative and arbitration proceedings must also trigger indemnity."}'::jsonb)
    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo shall indemnify and hold harmless Amazon and its parent, subsidiaries, affiliates, successors, assigns, licensees, sublicensees, distributors, exhibitors, and their respective officers, directors, employees, agents and representatives (collectively, ''Amazon Indemnitees'').', ARRAY['indemnify','hold harmless','Amazon','parent','subsidiaries','affiliates','successors','assigns','licensees','sublicensees','distributors','exhibitors','officers','directors','employees','agents','representatives','Amazon Indemnitees']::text[], '{"doc": "PSA_Principal_Terms", "section": "Indemnification", "note": "Comprehensive indemnitee list", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Comprehensive indemnitee list covering corporate family, downstream exploiters, and individual personnel. Essential for protecting Amazon''s exploitation chain."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, '''Amazon Indemnitees'' means Amazon Content Services LLC and each of its direct and indirect parent companies, subsidiaries and affiliates, including Amazon.com, Inc., together with their successors, assigns, licensees (including Amazon Prime Video licensees worldwide), and the officers, directors, employees and agents of any of the foregoing.', ARRAY['Amazon Indemnitees','Amazon Content Services LLC','parent companies','subsidiaries','affiliates','Amazon.com Inc','successors','assigns','licensees','Amazon Prime Video','worldwide','officers','directors','employees','agents']::text[], '{"doc": "PSA_Principal_Terms", "section": "Indemnification", "note": "Defined term with Amazon entities", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Explicitly includes Amazon.com, Inc. and Prime Video licensees. Named entities provide clarity while maintaining comprehensive coverage."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo''s indemnification extends to: (a) Amazon and all Amazon-related entities; (b) any party to whom Amazon assigns its rights under this Agreement; (c) any party that licenses or sublicenses rights in the Program from Amazon; (d) any broadcaster, streamer, or exhibitor exploiting the Program; and (e) each such party''s personnel.', ARRAY['indemnification','Amazon','Amazon-related entities','assigns','licenses','sublicenses','Program','broadcaster','streamer','exhibitor','exploiting','personnel']::text[], '{"doc": "PSA_Principal_Terms", "section": "Indemnification", "note": "Exploiter chain coverage", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Explicitly includes exploiters in the distribution chain (broadcasters, streamers, exhibitors). Essential for protecting downstream licensees who may face claims."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon Indemnitees include all parties in the Amazon corporate family and all parties deriving rights from Amazon''s exploitation of the Program. For the avoidance of doubt, Amazon may grant the benefit of this indemnification to any licensee or assignee without ProdCo''s consent.', ARRAY['Amazon Indemnitees','Amazon corporate family','deriving rights','exploitation','Program','grant benefit','indemnification','licensee','assignee','without','ProdCo''s consent']::text[], '{"doc": "PSA_Principal_Terms", "section": "Indemnification", "note": "Benefit extension without consent", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Explicitly authorizes Amazon to extend indemnification benefit to future licensees without ProdCo consent. Important for deal flexibility."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo shall indemnify each Amazon Indemnitee. The term ''Amazon Indemnitees'' includes any co-producer, co-financer, completion guarantor, production lender, or other party that Amazon may engage in connection with the Program''s production or financing, if Amazon notifies ProdCo of such party''s inclusion.', ARRAY['indemnify','Amazon Indemnitee','co-producer','co-financer','completion guarantor','production lender','production','financing','notifies','inclusion']::text[], '{"doc": "PSA_Principal_Terms", "section": "Indemnification", "note": "Production/financing parties included", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Extends to production and financing parties that Amazon may engage. Notification requirement provides ProdCo visibility while preserving Amazon flexibility."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon Indemnitees means Amazon, its affiliates, and all parties in the exploitation chain. Each Amazon Indemnitee is an intended third-party beneficiary of ProdCo''s indemnification obligations and may enforce such obligations directly against ProdCo.', ARRAY['Amazon Indemnitees','Amazon','affiliates','exploitation chain','intended third-party beneficiary','indemnification obligations','enforce','directly','against ProdCo']::text[], '{"doc": "PSA_Principal_Terms", "section": "Indemnification", "note": "Third-party beneficiary status", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Third-party beneficiary status allows indemnitees to enforce indemnification directly. Important for downstream parties that may not have privity with ProdCo."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo''s indemnification protects Amazon and all Amazon Indemnitees, whether existing now or in the future. ProdCo''s obligations shall extend automatically to any future affiliate, successor, or licensee without the need for amendment of this Agreement.', ARRAY['indemnification','Amazon','Amazon Indemnitees','existing now','future','extend automatically','future affiliate','successor','licensee','without','amendment']::text[], '{"doc": "PSA_Principal_Terms", "section": "Indemnification", "note": "Automatic extension to future parties", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Automatic extension to future parties eliminates need for Agreement amendments when new licensees or affiliates are added."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon Indemnitees include Amazon, its affiliates, successors, assigns, and licensees. ProdCo''s indemnification of third-party licensees and sublicensees shall be conditioned upon such parties agreeing to reasonable cooperation in defense of claims and providing ProdCo with requested information.', ARRAY['Amazon Indemnitees','Amazon','affiliates','successors','assigns','licensees','third-party licensees','sublicensees','conditioned','reasonable cooperation','defense','providing information']::text[], '{"doc": "Counterparty_Markup", "section": "Indemnification", "note": "Cooperation condition for licensees", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Conditioning licensee indemnification on reasonable cooperation is fair if it doesn''t create unreasonable burden. Legal should confirm cooperation requirements are workable."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo shall indemnify Amazon and its affiliates. Amazon''s licensees and sublicensees shall be included in the indemnification only to the extent Amazon has contractually required such parties to comply with confidentiality and exploitation restrictions consistent with this Agreement.', ARRAY['indemnify','Amazon','affiliates','licensees','sublicensees','included','only to extent','contractually required','comply','confidentiality','exploitation restrictions']::text[], '{"doc": "Counterparty_Markup", "section": "Indemnification", "note": "Licensee compliance condition", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Conditioning licensee inclusion on compliance requirements is reasonable protection against rogue licensees. Amazon typically includes such requirements anyway."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon Indemnitees include Amazon and its affiliates, successors, and assigns. With respect to licensees and sublicensees, ProdCo''s indemnification shall extend only to losses arising from ProdCo''s content and activities, and not to losses arising from such licensee''s independent conduct.', ARRAY['Amazon Indemnitees','Amazon','affiliates','successors','assigns','licensees','sublicensees','losses','ProdCo''s content','activities','not','licensee''s independent conduct']::text[], '{"doc": "Counterparty_Markup", "section": "Indemnification", "note": "Licensee independent conduct carveout", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Carveout for licensee independent conduct is reasonable\u2014ProdCo shouldn''t indemnify for licensee''s own misconduct unrelated to Program content."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo shall indemnify Amazon and its controlled affiliates. With respect to joint ventures or minority-owned entities in which Amazon participates, ProdCo''s indemnification shall apply only to the extent of Amazon''s ownership interest in such entity.', ARRAY['indemnify','Amazon','controlled affiliates','joint ventures','minority-owned entities','Amazon participates','indemnification','extent','Amazon''s ownership interest']::text[], '{"doc": "Counterparty_Markup", "section": "Indemnification", "note": "Pro-rata for JV/minority interests", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Pro-rata indemnification for JV/minority interests is reasonable limitation\u2014ProdCo shouldn''t fully indemnify entities Amazon doesn''t control."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon Indemnitees include all exploiters of the Program. If Amazon assigns this Agreement or licenses Program rights, Amazon shall notify ProdCo in writing of the assignee or licensee, and such party shall be added to the Amazon Indemnitees upon such notification.', ARRAY['Amazon Indemnitees','exploiters','Program','assigns','licenses','rights','notify ProdCo','writing','assignee','licensee','added','upon notification']::text[], '{"doc": "Counterparty_Markup", "section": "Indemnification", "note": "Notification of new indemnitees", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Notification of new indemnitees is minimal burden that provides ProdCo visibility. Doesn''t limit Amazon''s assignment rights."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo shall indemnify Amazon, its affiliates, and downstream licensees. Amazon shall include in its license agreements a provision requiring licensees to provide prompt notice to Amazon of any indemnifiable claims, and Amazon shall promptly forward such notices to ProdCo.', ARRAY['indemnify','Amazon','affiliates','downstream licensees','include','license agreements','provision','licensees','prompt notice','indemnifiable claims','forward','ProdCo']::text[], '{"doc": "Counterparty_Markup", "section": "Indemnification", "note": "Licensee notice flow-through", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Notice flow-through from licensees to ProdCo is helpful procedural mechanism that improves claim handling without limiting indemnification scope."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall indemnify Amazon only. ProdCo''s indemnification shall not extend to Amazon''s affiliates, parent companies, subsidiaries, successors, assigns, licensees, sublicensees, or any other third party.', ARRAY['indemnify','Amazon only','not extend','affiliates','parent companies','subsidiaries','successors','assigns','licensees','sublicensees','third party']::text[], '{"doc": "Counterparty_Markup", "section": "Indemnification", "note": "Amazon-only indemnification", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Limiting indemnification to Amazon only leaves entire exploitation chain (affiliates, licensees, distributors) without protection. All exploiters need indemnification coverage."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon Indemnitees include Amazon and its affiliates existing as of the Effective Date. Future affiliates, successors, assigns, or licensees shall not be covered unless ProdCo provides written consent to their inclusion.', ARRAY['Amazon Indemnitees','Amazon','affiliates','existing','Effective Date','future affiliates','successors','assigns','licensees','not covered','written consent']::text[], '{"doc": "Counterparty_Markup", "section": "Indemnification", "note": "Point-in-time with consent required", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Requiring ProdCo consent for future indemnitees gives ProdCo blocking power over Amazon''s business deals. Indemnification must extend automatically to future parties."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall indemnify Amazon and its direct, wholly-owned subsidiaries. Affiliates, joint ventures, minority-owned entities, and entities in which Amazon has less than 100% ownership shall not be included in the Amazon Indemnitees.', ARRAY['indemnify','Amazon','direct','wholly-owned subsidiaries','affiliates','joint ventures','minority-owned','less than 100%','not included']::text[], '{"doc": "Counterparty_Markup", "section": "Indemnification", "note": "Wholly-owned only", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Limiting to wholly-owned subsidiaries excludes many Amazon entities that may exploit the Program. Indemnification must cover the full Amazon family regardless of ownership percentage."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall indemnify Amazon and its affiliates. Amazon''s licensees and sublicensees may be added to the Amazon Indemnitees only if: (a) ProdCo approves such licensee in writing; and (b) the licensee agrees to be bound by confidentiality obligations equivalent to Amazon''s.', ARRAY['indemnify','Amazon','affiliates','licensees','sublicensees','added','only if','ProdCo approves','writing','confidentiality obligations','equivalent']::text[], '{"doc": "Counterparty_Markup", "section": "Indemnification", "note": "ProdCo approval required for licensees", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Requiring ProdCo approval for licensees gives ProdCo inappropriate control over Amazon''s licensing decisions. Licensees must be automatically covered."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon Indemnitees include Amazon and its affiliates. ProdCo''s indemnification of Amazon''s licensees shall be limited to the first five (5) major territorial licensees identified by Amazon. Additional licensees beyond this number shall not be covered.', ARRAY['Amazon Indemnitees','Amazon','affiliates','indemnification','licensees','limited','first five','major territorial','additional licensees','not covered']::text[], '{"doc": "Counterparty_Markup", "section": "Indemnification", "note": "Numerical limit on licensees", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Arbitrary numerical limit on licensee coverage is unworkable for global streaming distribution. All licensees exploiting the Program need indemnification coverage."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall indemnify Amazon and its affiliates against claims by unrelated third parties. Claims asserted by Amazon''s licensees, sublicensees, or other parties in the exploitation chain against Amazon shall not be covered by ProdCo''s indemnification.', ARRAY['indemnify','Amazon','affiliates','claims','unrelated third parties','claims','licensees','sublicensees','exploitation chain','against Amazon','not covered']::text[], '{"doc": "Counterparty_Markup", "section": "Indemnification", "note": "Exploitation chain claims excluded", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Excluding claims by exploitation chain parties (licensees suing Amazon) creates significant gap. If licensee claims arise from ProdCo content issues, ProdCo should indemnify."}'::jsonb)
    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo shall indemnify Amazon against Losses arising from any breach or alleged breach of ProdCo''s representations, warranties, covenants or obligations. For the avoidance of doubt, indemnification applies upon assertion of a claim alleging breach, regardless of whether such breach is ultimately proven.', ARRAY['indemnify','Losses','breach','alleged breach','representations','warranties','covenants','obligations','assertion','claim','alleging breach','regardless','ultimately proven']::text[], '{"doc": "PSA_Principal_Terms", "section": "Indemnification", "note": "Alleged breach coverage with clarification", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Standard ''alleged breach'' language with clarification that indemnity applies upon claim assertion. Amazon typically prefers to DELETE ''alleged breach'' language, but this formulation is acceptable."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo''s indemnification covers claims based upon facts that, if true, would constitute a breach by ProdCo. Indemnification shall apply to defense of such claims regardless of whether the underlying facts are disputed or whether the claim is ultimately successful.', ARRAY['indemnification','claims','facts','if true','constitute breach','defense','claims','regardless','underlying facts','disputed','claim','ultimately successful']::text[], '{"doc": "PSA_Principal_Terms", "section": "Indemnification", "note": "Facts-if-true formulation", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "''Facts if true would constitute breach'' is functionally equivalent to ''alleged breach'' but focuses on factual allegations rather than breach characterization."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Indemnification applies to any claim that, on its face, asserts facts or circumstances that would implicate ProdCo''s representations, warranties or obligations if such facts were established. ProdCo shall defend and indemnify from the date the claim is asserted through final resolution.', ARRAY['claim','on its face','asserts facts','circumstances','implicate','representations','warranties','obligations','if established','defend','indemnify','date asserted','final resolution']::text[], '{"doc": "PSA_Principal_Terms", "section": "Indemnification", "note": "Facial sufficiency standard", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Facial sufficiency standard triggers indemnity based on claim allegations, not proof. Coverage from assertion through resolution ensures complete protection."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo shall indemnify and defend against any third-party claim alleging breach by ProdCo or alleging facts that, if proven, would constitute such breach. ProdCo''s indemnification obligation shall not depend upon any admission or finding of breach.', ARRAY['indemnify','defend','third-party claim','alleging breach','alleging facts','if proven','constitute breach','obligation','not depend','admission','finding']::text[], '{"doc": "PSA_Principal_Terms", "section": "Indemnification", "note": "No admission/finding dependency", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Explicit statement that indemnity doesn''t depend on admission or finding eliminates arguments that ProdCo must be proven at fault before indemnity applies."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Indemnification is triggered by any claim arising from or relating to the Program or ProdCo''s performance, including claims asserting breach, infringement, defamation, or other legal theories. The triggering claim need not specifically identify ProdCo as the responsible party.', ARRAY['triggered','claim','arising from','relating to','Program','ProdCo''s performance','asserting','breach','infringement','defamation','legal theories','not specifically identify','ProdCo','responsible party']::text[], '{"doc": "PSA_Principal_Terms", "section": "Indemnification", "note": "Broad claim trigger", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Broad trigger covering any claim relating to Program or performance, not requiring ProdCo be named. Comprehensive coverage for indirect claims."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Upon Amazon''s receipt of any claim that may be subject to indemnification, Amazon shall notify ProdCo and ProdCo shall promptly assume defense of such claim. ProdCo''s obligation to indemnify and defend arises upon notification, not upon any determination of breach validity.', ARRAY['receipt','claim','subject to indemnification','notify ProdCo','promptly assume defense','obligation','arises','notification','not upon','determination','breach validity']::text[], '{"doc": "PSA_Principal_Terms", "section": "Indemnification", "note": "Notification-triggered defense", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Defense obligation arises upon notification, not upon breach determination. Ensures immediate defense without waiting for liability analysis."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo shall indemnify against Losses from breach of this Agreement. For indemnification to apply, Amazon need only demonstrate that a claim has been asserted alleging facts that relate to ProdCo''s representations or obligations; Amazon need not prove the underlying breach.', ARRAY['indemnify','Losses','breach','indemnification','apply','Amazon demonstrate','claim asserted','alleging facts','relate to','representations','obligations','need not prove','underlying breach']::text[], '{"doc": "PSA_Principal_Terms", "section": "Indemnification", "note": "Proof burden clarification", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Clarifies Amazon''s burden is only to show claim was asserted with relevant allegations, not to prove breach. Appropriate allocation of proof burden."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo''s indemnification applies to alleged breaches. If ProdCo disputes that a claim involves an indemnifiable alleged breach, ProdCo shall nonetheless assume defense pending resolution of the dispute, and the parties shall work in good faith to resolve such dispute promptly.', ARRAY['indemnification','alleged breaches','ProdCo disputes','claim','indemnifiable','alleged breach','nonetheless','assume defense','pending resolution','work in good faith','resolve','promptly']::text[], '{"doc": "Counterparty_Markup", "section": "Indemnification", "note": "Defend pending dispute resolution", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Defense pending dispute resolution ensures Amazon is protected while indemnification applicability is determined. Good faith resolution process is reasonable."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Indemnification covers alleged breaches. If a claim is asserted that ProdCo believes is frivolous or clearly not indemnifiable, ProdCo may request Amazon''s consent before assuming defense, which consent shall not be unreasonably withheld; if Amazon withholds consent, Amazon shall assume initial defense pending resolution.', ARRAY['alleged breaches','claim','frivolous','not indemnifiable','request','Amazon''s consent','defense','not unreasonably withheld','Amazon withholds','Amazon assume','initial defense','pending']::text[], '{"doc": "Counterparty_Markup", "section": "Indemnification", "note": "Frivolous claim consent process", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Process for clearly frivolous claims is reasonable with Amazon assuming defense if consent withheld. Prevents abuse but preserves Amazon protection."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Alleged breach triggers indemnification. If the underlying claim is dismissed or resolved in ProdCo''s favor with a finding that no breach occurred, ProdCo shall remain responsible for all defense costs incurred prior to such resolution, but shall have no further indemnification obligation for that claim.', ARRAY['alleged breach','triggers','indemnification','claim dismissed','resolved','ProdCo''s favor','no breach','responsible','defense costs','prior to resolution','no further','indemnification obligation']::text[], '{"doc": "Counterparty_Markup", "section": "Indemnification", "note": "Resolution of non-breach claims", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Clarification that defense costs are covered even for claims ultimately resolved as non-breach is appropriate. Confirms indemnification purpose includes defense."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Indemnification applies to alleged breaches. The parties agree that Amazon''s notification of a claim shall include available details about the claim''s allegations, and ProdCo shall have five (5) business days to assume defense before Amazon may engage its own counsel at ProdCo''s expense.', ARRAY['alleged breaches','notification','available details','allegations','ProdCo','five business days','assume defense','before','Amazon engage','own counsel','ProdCo''s expense']::text[], '{"doc": "Counterparty_Markup", "section": "Indemnification", "note": "Response timeline for defense assumption", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Five-day window for ProdCo to assume defense before Amazon self-defends is reasonable timeline that doesn''t prejudice Amazon''s ability to respond to claims."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Indemnification covers breach and alleged breach. If a claim alleges breach but is ultimately resolved with a settlement that makes no admission of breach, ProdCo''s indemnification shall cover the settlement amount unless ProdCo can demonstrate that Amazon acted unreasonably in accepting such settlement.', ARRAY['breach','alleged breach','claim','alleges','ultimately resolved','settlement','no admission','indemnification','cover','settlement amount','unless','Amazon acted unreasonably','accepting settlement']::text[], '{"doc": "Counterparty_Markup", "section": "Indemnification", "note": "Settlement coverage with reasonableness", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Settlement coverage with unreasonableness defense is reasonable if Amazon''s settlement discretion is preserved. ''Unless ProdCo can demonstrate'' places burden appropriately."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo shall indemnify against alleged breaches. For claims asserting solely ''alleged breach'' without specifying the representations or obligations allegedly breached, Amazon shall provide ProdCo with its good faith analysis of which Agreement provisions may be implicated.', ARRAY['indemnify','alleged breaches','claims','solely alleged breach','without specifying','representations','obligations','Amazon provide','good faith analysis','provisions','implicated']::text[], '{"doc": "Counterparty_Markup", "section": "Indemnification", "note": "Amazon provision identification", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Amazon''s provision of good faith analysis of implicated provisions is helpful procedural cooperation that doesn''t limit indemnification scope."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall indemnify Amazon against actual breaches only. Claims alleging breach that are not substantiated by a final judgment or arbitration award finding actual breach shall not be subject to indemnification.', ARRAY['indemnify','actual breaches only','claims','alleging breach','not substantiated','final judgment','arbitration award','finding','actual breach','not subject','indemnification']::text[], '{"doc": "Counterparty_Markup", "section": "Indemnification", "note": "Actual breach only with judgment required", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Requiring final judgment of actual breach excludes defense costs and settlement coverage. Indemnification must cover alleged breaches regardless of outcome."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo''s indemnification applies only to proven breaches. ProdCo shall reimburse Amazon''s defense costs only if the underlying claim results in a finding of breach by ProdCo; if the claim is settled or dismissed without such finding, Amazon shall bear its own defense costs.', ARRAY['indemnification','proven breaches only','reimburse','defense costs','only if','finding of breach','settled','dismissed','without finding','Amazon bear','own defense costs']::text[], '{"doc": "Counterparty_Markup", "section": "Indemnification", "note": "Proven breach with Amazon self-paying defense", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Requiring proven breach for defense cost reimbursement completely undermines indemnification purpose. Defense costs must be covered regardless of outcome."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Indemnification applies to breach, but ''alleged breach'' is deleted. ProdCo shall have no obligation to indemnify or defend until a court or arbitrator has made a preliminary determination that the claim has a reasonable likelihood of success on the merits.', ARRAY['breach','alleged breach','deleted','no obligation','indemnify','defend','until','court','arbitrator','preliminary determination','reasonable likelihood','success','merits']::text[], '{"doc": "Counterparty_Markup", "section": "Indemnification", "note": "Alleged breach deleted with likelihood requirement", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Deleting ''alleged breach'' AND requiring preliminary determination of likelihood of success creates massive gap. Amazon would bear all defense costs until such determination\u2014potentially years into litigation."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall indemnify against breaches. With respect to claims alleging breach, ProdCo shall have no indemnification obligation if ProdCo disputes the breach in good faith. Amazon and ProdCo shall submit any dispute regarding breach to binding arbitration prior to indemnification applying.', ARRAY['indemnify','breaches','claims alleging breach','no obligation','ProdCo disputes','good faith','submit','dispute','binding arbitration','prior to','indemnification applying']::text[], '{"doc": "Counterparty_Markup", "section": "Indemnification", "note": "Arbitration prerequisite for indemnification", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Requiring arbitration before indemnification applies defeats the purpose\u2014Amazon would be undefended during potentially lengthy arbitration. Good faith dispute should not suspend indemnification."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Indemnification applies to breach. ''Alleged breach'' language is rejected as overly broad. ProdCo''s indemnification obligation shall commence only after Amazon provides ProdCo with (i) copies of all claim documents; (ii) detailed legal analysis of breach; and (iii) evidence substantiating the alleged breach.', ARRAY['breach','alleged breach','rejected','overly broad','obligation commence','only after','copies','claim documents','detailed legal analysis','evidence','substantiating','alleged breach']::text[], '{"doc": "Counterparty_Markup", "section": "Indemnification", "note": "Extensive prerequisites for indemnification", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Extensive prerequisites (legal analysis, substantiating evidence) before indemnification applies is unworkable. Amazon shouldn''t need to prove its case to ProdCo before receiving defense."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall indemnify for actual breaches. For alleged breaches, ProdCo shall advance defense costs as a loan, which loan shall be repaid by Amazon if the claim is resolved without a finding of actual breach by ProdCo.', ARRAY['indemnify','actual breaches','alleged breaches','advance','defense costs','loan','repaid','Amazon','resolved','without finding','actual breach']::text[], '{"doc": "Counterparty_Markup", "section": "Indemnification", "note": "Defense costs as repayable loan", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Treating defense cost coverage as a repayable loan for alleged breaches shifts risk to Amazon for non-meritorious claims. Defense costs must be ProdCo''s permanent obligation."}'::jsonb)
    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon shall indemnify and hold harmless ProdCo from and against third-party claims arising directly from Amazon''s material breach of Amazon''s express representations and warranties set forth in Section [X] of this Agreement, subject to the limitations and conditions set forth herein.', ARRAY['Amazon','indemnify','hold harmless','ProdCo','third-party claims','arising directly','Amazon''s material breach','express representations','warranties','Section','subject to','limitations','conditions']::text[], '{"doc": "PSA_Fallbacks", "section": "Amazon Indemnification", "note": "Limited Amazon indemnity scope", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Amazon''s indemnity is appropriately limited to its own material breach of express reps/warranties. ''Arising directly'' and ''material breach'' qualifiers narrow scope. Subject to limitations language preserves other restrictions."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon agrees to indemnify ProdCo against Losses arising from third-party claims to the extent such claims arise from Amazon''s breach of Amazon''s representations regarding Amazon''s authority to enter into this Agreement, as set forth in Section [X].', ARRAY['Amazon','indemnify','ProdCo','Losses','third-party claims','to the extent','arise from','Amazon''s breach','representations','authority','enter into','Agreement','Section']::text[], '{"doc": "PSA_Fallbacks", "section": "Amazon Indemnification", "note": "Authority representation indemnity only", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Limits Amazon indemnity to breach of authority representation only, which is the narrowest acceptable scope. ''To the extent'' proportionality language is appropriate."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon''s indemnification of ProdCo shall be limited to claims arising from: (a) Amazon''s breach of Amazon''s express representations set forth in this Agreement; or (b) Amazon''s gross negligence or willful misconduct in connection with this Agreement. This indemnification is subject to all limitations, exclusions and conditions set forth herein.', ARRAY['Amazon''s indemnification','limited to','claims','Amazon''s breach','express representations','gross negligence','willful misconduct','subject to','limitations','exclusions','conditions']::text[], '{"doc": "PSA_Fallbacks", "section": "Amazon Indemnification", "note": "Breach plus gross negligence/willful misconduct", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Extends Amazon indemnity to gross negligence/willful misconduct in addition to rep breach. Still appropriately narrow with limitations carveout."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon shall indemnify ProdCo for third-party claims arising from Amazon''s material breach of this Agreement, provided that: (i) such breach is not caused by or attributable to any act or omission of ProdCo; (ii) ProdCo provides prompt notice; and (iii) ProdCo cooperates fully with Amazon''s defense.', ARRAY['Amazon','indemnify','ProdCo','third-party claims','Amazon''s material breach','provided','not caused by','attributable to','ProdCo','prompt notice','cooperates','Amazon''s defense']::text[], '{"doc": "PSA_Fallbacks", "section": "Amazon Indemnification", "note": "Conditions on Amazon indemnity", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Conditions (no ProdCo fault, notice, cooperation) appropriately limit Amazon''s exposure while providing coverage for genuine Amazon breaches."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'To the extent Amazon is required to provide indemnification hereunder, Amazon shall indemnify ProdCo against Losses from third-party claims arising directly and solely from Amazon''s breach of Amazon''s representations in Section [X]. For the avoidance of doubt, Amazon''s indemnification shall not cover any claims arising from the Program content or ProdCo''s production activities.', ARRAY['Amazon','indemnification','ProdCo','Losses','third-party claims','directly and solely','Amazon''s breach','representations','avoidance of doubt','not cover','Program content','ProdCo''s production']::text[], '{"doc": "PSA_Fallbacks", "section": "Amazon Indemnification", "note": "Explicit content/production exclusion", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Explicitly excludes Program content and production claims from Amazon indemnity. Clear delineation of responsibility between parties."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon''s indemnification obligation shall apply only to claims arising from Amazon''s breach of Section [X] (Amazon Representations). Amazon''s indemnification shall not extend to: (a) claims relating to Program content; (b) claims relating to ProdCo''s performance; (c) claims that would be covered by ProdCo''s indemnity; or (d) claims arising from Amazon''s exercise of rights granted hereunder.', ARRAY['Amazon''s indemnification','only','claims','Amazon''s breach','Section','not extend','Program content','ProdCo''s performance','ProdCo''s indemnity','Amazon''s exercise','rights granted']::text[], '{"doc": "PSA_Fallbacks", "section": "Amazon Indemnification", "note": "Enumerated exclusions", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Enumerated exclusions clearly carve out content claims, ProdCo performance claims, ProdCo-indemnified claims, and rights-exercise claims. Comprehensive limitation."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'If Amazon breaches any representation or warranty expressly made by Amazon in this Agreement, Amazon shall indemnify ProdCo against documented, direct Losses arising from third-party claims based on such breach, subject to the aggregate cap and other limitations set forth in Section [Y].', ARRAY['Amazon breaches','representation','warranty','expressly made','indemnify','ProdCo','documented','direct Losses','third-party claims','based on','breach','subject to','aggregate cap','limitations']::text[], '{"doc": "PSA_Fallbacks", "section": "Amazon Indemnification", "note": "Documented direct losses with cap reference", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "''Documented, direct Losses'' limits to proven direct damages. Reference to aggregate cap and other limitations ensures full protection framework applies."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon shall indemnify ProdCo from third-party claims arising from Amazon''s breach of this Agreement. This indemnification shall be proportionate to Amazon''s contribution to the claim and shall not apply to claims primarily arising from ProdCo''s acts or omissions.', ARRAY['Amazon','indemnify','ProdCo','third-party claims','Amazon''s breach','proportionate','Amazon''s contribution','not apply','claims','primarily','ProdCo''s acts','omissions']::text[], '{"doc": "Counterparty_Markup", "section": "Amazon Indemnification", "note": "Proportionate indemnification", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Proportionate indemnification based on Amazon''s contribution is reasonable allocation. ''Primarily'' threshold for ProdCo exclusion preserves appropriate balance."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon''s indemnification covers claims arising from Amazon''s breach of express representations. If a claim involves both Amazon breach and ProdCo breach, Amazon''s indemnity shall apply only to the portion of Losses attributable to Amazon''s breach, as determined through good faith consultation between the parties.', ARRAY['Amazon''s indemnification','Amazon''s breach','express representations','claim involves','both','Amazon breach','ProdCo breach','indemnity','portion of Losses','attributable','good faith consultation']::text[], '{"doc": "Counterparty_Markup", "section": "Amazon Indemnification", "note": "Mixed-fault allocation", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Mixed-fault allocation with good faith consultation is reasonable approach for claims with shared responsibility."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon shall indemnify ProdCo for claims arising from Amazon''s material breach. For purposes of this indemnification, ''material breach'' means a breach that has a significant adverse effect on ProdCo''s ability to perform its obligations or on ProdCo''s business reputation.', ARRAY['Amazon','indemnify','ProdCo','claims','Amazon''s material breach','material breach means','significant adverse effect','ProdCo''s ability','perform obligations','business reputation']::text[], '{"doc": "Counterparty_Markup", "section": "Amazon Indemnification", "note": "Material breach definition", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Definition of ''material breach'' for Amazon indemnity purposes is reasonable if it doesn''t create disputes. ProdCo-focused definition is appropriate for their indemnity."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon agrees to indemnify ProdCo from claims arising from Amazon''s breach of representations. Amazon''s indemnification shall include reasonable attorneys'' fees and defense costs if ProdCo is required to defend claims arising from Amazon''s breach and Amazon declines to assume defense.', ARRAY['Amazon','indemnify','ProdCo','claims','Amazon''s breach','representations','reasonable attorneys'' fees','defense costs','ProdCo','defend','Amazon declines','assume defense']::text[], '{"doc": "Counterparty_Markup", "section": "Amazon Indemnification", "note": "Defense cost coverage if Amazon declines", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Defense cost coverage when Amazon declines to assume defense is fair\u2014if claim is Amazon''s responsibility, ProdCo shouldn''t bear defense costs."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon''s indemnification of ProdCo shall apply to claims from Amazon''s breach. The parties acknowledge that Amazon''s indemnification is secondary to any applicable insurance coverage, and ProdCo shall first pursue applicable insurance before seeking indemnification from Amazon.', ARRAY['Amazon''s indemnification','ProdCo','claims','Amazon''s breach','acknowledge','secondary','applicable insurance','pursue insurance','before seeking','indemnification','Amazon']::text[], '{"doc": "Counterparty_Markup", "section": "Amazon Indemnification", "note": "Insurance priority", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Insurance priority for Amazon indemnity claims is reasonable given Amazon typically requires production insurance. Doesn''t eliminate Amazon obligation, just orders recovery."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon shall indemnify ProdCo for claims arising from Amazon''s breach. This indemnification shall survive termination of this Agreement for a period of three (3) years, except for claims based on fraud or willful misconduct, which shall survive indefinitely.', ARRAY['Amazon','indemnify','ProdCo','claims','Amazon''s breach','survive termination','three years','except','fraud','willful misconduct','survive indefinitely']::text[], '{"doc": "Counterparty_Markup", "section": "Amazon Indemnification", "note": "Three-year survival with fraud exception", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Three-year survival for Amazon indemnity with fraud/willful misconduct exception is reasonable limitation. ProdCo indemnity typically survives longer due to content nature."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon shall indemnify and hold harmless ProdCo from and against any and all claims, damages, losses, costs and expenses arising from or relating to Amazon''s exploitation of the Program, including claims of infringement, defamation, or privacy violation.', ARRAY['Amazon','indemnify','hold harmless','ProdCo','any and all claims','damages','losses','costs','arising from','relating to','Amazon''s exploitation','Program','infringement','defamation','privacy']::text[], '{"doc": "Counterparty_Proposal", "section": "Amazon Indemnification", "note": "Broad exploitation indemnity", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Amazon cannot indemnify for exploitation claims\u2014these arise from Program content which is ProdCo''s responsibility. This would effectively shift all content liability to Amazon."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon shall indemnify ProdCo against all claims arising from the Program to the same extent and scope as ProdCo indemnifies Amazon. The parties'' indemnification obligations shall be mutual and equivalent.', ARRAY['Amazon','indemnify','ProdCo','all claims','arising from','Program','same extent','scope','ProdCo indemnifies','Amazon','mutual','equivalent']::text[], '{"doc": "Counterparty_Proposal", "section": "Amazon Indemnification", "note": "Mirror indemnity", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Mirror indemnity ignores fundamental asymmetry\u2014ProdCo creates content, Amazon exploits. Content claims are ProdCo''s responsibility. Equivalence is inappropriate."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon shall indemnify ProdCo against claims arising from: (a) Amazon''s breach; (b) Amazon''s modifications to the Program after delivery; (c) Amazon''s marketing and promotional activities; (d) Amazon''s distribution and licensing activities; and (e) Amazon''s exploitation decisions.', ARRAY['Amazon','indemnify','ProdCo','claims','Amazon''s breach','modifications','after delivery','marketing','promotional','distribution','licensing','exploitation decisions']::text[], '{"doc": "Counterparty_Proposal", "section": "Amazon Indemnification", "note": "Expansive operational indemnity", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Expansive indemnity for modifications, marketing, distribution, and exploitation shifts content liability to Amazon. These claims typically arise from content ProdCo created."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon''s indemnification shall cover all claims that ProdCo could not have anticipated or prevented through its clearance processes, as the risk of such claims should properly rest with the party that controls exploitation.', ARRAY['Amazon''s indemnification','all claims','ProdCo could not have anticipated','prevented','clearance processes','risk','rest with','party','controls exploitation']::text[], '{"doc": "Counterparty_Proposal", "section": "Amazon Indemnification", "note": "Unanticipated claims indemnity", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "''Could not have anticipated'' standard is impossible to administer and would shift virtually all claims to Amazon. ProdCo is responsible for content clearance regardless of anticipation."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon shall indemnify ProdCo against claims arising from the Program in any territory where Amazon exploits the Program without ProdCo''s express written consent, as ProdCo cannot warrant clearance for unauthorized exploitation territories.', ARRAY['Amazon','indemnify','ProdCo','claims','Program','territory','Amazon exploits','without','ProdCo''s consent','warrant clearance','unauthorized','territories']::text[], '{"doc": "Counterparty_Proposal", "section": "Amazon Indemnification", "note": "Territorial consent-based indemnity", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Amazon has worldwide exploitation rights and doesn''t need ProdCo consent for territories. Conditioning indemnification on consent flips the rights structure entirely."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon shall indemnify ProdCo for claims arising from Amazon''s failure to obtain proper clearances for exploitation of the Program. ProdCo''s clearance obligations relate only to production; exploitation clearances are Amazon''s responsibility.', ARRAY['Amazon','indemnify','ProdCo','claims','Amazon''s failure','obtain clearances','exploitation','Program','ProdCo''s clearance','production only','exploitation clearances','Amazon''s responsibility']::text[], '{"doc": "Counterparty_Proposal", "section": "Amazon Indemnification", "note": "Split clearance responsibility", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "ProdCo clears content for all exploitation, not just production. This attempts to split clearance responsibility in a way that shifts content liability to Amazon."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon shall indemnify ProdCo against claims arising from the Program to the extent E&O insurance does not cover such claims. Amazon''s indemnification shall function as excess coverage above insurance limits.', ARRAY['Amazon','indemnify','ProdCo','claims','Program','to the extent','E&O insurance','does not cover','Amazon''s indemnification','excess coverage','above insurance']::text[], '{"doc": "Counterparty_Proposal", "section": "Amazon Indemnification", "note": "Amazon as excess insurer", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Making Amazon the excess insurer for Program claims shifts content liability to Amazon for claims above insurance limits. ProdCo bears this responsibility, not Amazon."}'::jsonb)
    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Notwithstanding any Amazon indemnification obligation, Amazon shall have no obligation to indemnify ProdCo for any claim arising from or relating to: (a) the Program or any Materials; (b) any act or omission of ProdCo; (c) any breach by ProdCo of this Agreement; or (d) any matter for which ProdCo is obligated to indemnify Amazon.', ARRAY['notwithstanding','Amazon indemnification','no obligation','indemnify ProdCo','claim','arising from','relating to','Program','Materials','act','omission','ProdCo','breach','ProdCo obligated','indemnify Amazon']::text[], '{"doc": "PSA_Principal_Terms", "section": "Amazon Indemnification", "note": "Standard exclusions from Amazon indemnity", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Standard exclusions ensuring Amazon doesn''t indemnify for Program content, ProdCo conduct, ProdCo breach, or ProdCo-indemnified matters. Essential carveouts."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon''s indemnification expressly excludes claims based upon: (i) the content of the Program, including any allegations of infringement, defamation, privacy violation, or moral rights; (ii) ProdCo''s production activities; (iii) ProdCo''s personnel; or (iv) any underlying rights or clearances.', ARRAY['Amazon''s indemnification','expressly excludes','claims','content','Program','infringement','defamation','privacy','moral rights','production activities','personnel','underlying rights','clearances']::text[], '{"doc": "PSA_Principal_Terms", "section": "Amazon Indemnification", "note": "Content claims exclusion", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Explicitly excludes content-based claims (infringement, defamation, privacy, moral rights) from Amazon''s indemnity. These are ProdCo''s core responsibilities."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon shall not be obligated to indemnify ProdCo for any claim that arises from or relates to any representation, warranty, covenant or obligation of ProdCo under this Agreement, regardless of whether Amazon''s actions contributed to such claim.', ARRAY['Amazon','not obligated','indemnify ProdCo','claim','arises from','relates to','representation','warranty','covenant','obligation','ProdCo','regardless','Amazon''s actions','contributed']::text[], '{"doc": "PSA_Principal_Terms", "section": "Amazon Indemnification", "note": "ProdCo obligation exclusion even with Amazon contribution", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Excludes claims relating to ProdCo obligations even if Amazon contributed. ProdCo''s representations create primary responsibility regardless of Amazon''s role."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Exclusions from Amazon indemnification include: claims arising from the Program as delivered by ProdCo; claims arising from Materials created by ProdCo; claims relating to ProdCo''s chain of title; claims involving ProdCo''s personnel or contractors; and claims based on facts that would trigger ProdCo''s indemnity.', ARRAY['Exclusions','Amazon indemnification','claims','Program as delivered','Materials created','chain of title','personnel','contractors','claims','facts','trigger ProdCo''s indemnity']::text[], '{"doc": "PSA_Principal_Terms", "section": "Amazon Indemnification", "note": "Enumerated exclusions", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Comprehensive enumeration of exclusions covering delivered content, created materials, chain of title, personnel, and ProdCo-indemnified matters."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'For the avoidance of doubt, Amazon''s indemnification shall not apply to any claim that would not have arisen but for the content of the Program or ProdCo''s creation of such content. The risk of content-related claims rests with ProdCo as the content creator.', ARRAY['avoidance of doubt','Amazon''s indemnification','not apply','claim','would not have arisen','but for','content','Program','ProdCo''s creation','risk','content-related claims','rests with ProdCo','content creator']::text[], '{"doc": "PSA_Principal_Terms", "section": "Amazon Indemnification", "note": "But-for causation exclusion", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "''But for'' causation test ensures content-caused claims are excluded from Amazon''s indemnity. Explicitly assigns content risk to ProdCo as creator."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon''s indemnification does not cover claims relating to: (a) any inaccuracy in ProdCo''s representations; (b) any failure by ProdCo to perform its obligations; (c) any negligent or wrongful act of ProdCo; (d) any infringement, defamation, or privacy claim arising from Program content; or (e) any production-related claim.', ARRAY['Amazon''s indemnification','does not cover','inaccuracy','ProdCo''s representations','failure','perform obligations','negligent','wrongful act','infringement','defamation','privacy','Program content','production-related claim']::text[], '{"doc": "PSA_Principal_Terms", "section": "Amazon Indemnification", "note": "Comprehensive claim type exclusions", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Comprehensive exclusion covering ProdCo rep inaccuracy, performance failure, negligence/wrongful acts, content claims, and production claims. Complete protection."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon shall not indemnify ProdCo for claims arising from Amazon''s exercise of any right expressly granted under this Agreement, including Amazon''s right to edit, modify, adapt, or otherwise alter the Program. Such exercise of rights shall not constitute breach triggering indemnification.', ARRAY['Amazon','not indemnify','ProdCo','claims','Amazon''s exercise','right expressly granted','edit','modify','adapt','alter','Program','exercise of rights','not constitute breach']::text[], '{"doc": "PSA_Principal_Terms", "section": "Amazon Indemnification", "note": "Rights exercise exclusion", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Amazon''s exercise of granted rights (edit, modify, adapt) cannot trigger indemnification. These are rights ProdCo has granted, not Amazon breaches."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon''s indemnification excludes content claims except to the extent such claims arise solely and directly from Amazon''s post-delivery modifications that introduce new infringing or defamatory material not present in ProdCo''s delivered Program.', ARRAY['Amazon''s indemnification','excludes','content claims','except','solely and directly','Amazon''s post-delivery modifications','introduce','new infringing','defamatory material','not present','delivered Program']::text[], '{"doc": "Counterparty_Markup", "section": "Amazon Indemnification", "note": "Amazon modification exception", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Exception for Amazon-introduced infringing/defamatory material is fair allocation. ''Solely and directly'' and ''not present'' qualifiers appropriately limit scope."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Exclusions from Amazon''s indemnity include content claims. However, if Amazon''s marketing materials contain statements about the Program that are false or misleading and not derived from ProdCo-provided materials, Amazon shall be responsible for claims arising therefrom.', ARRAY['Exclusions','Amazon''s indemnity','content claims','however','Amazon''s marketing','statements','false','misleading','not derived','ProdCo-provided','Amazon responsible','claims','arising therefrom']::text[], '{"doc": "Counterparty_Markup", "section": "Amazon Indemnification", "note": "Amazon marketing statement exception", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Amazon responsibility for its own false/misleading marketing statements not derived from ProdCo materials is fair. Amazon controls its marketing."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Content claims are excluded from Amazon''s indemnity. If a content claim arises from Amazon''s direction to include specific material that ProdCo objected to in writing prior to inclusion, and such material is the sole basis for the claim, Amazon''s exclusion shall not apply to that claim.', ARRAY['Content claims','excluded','Amazon''s indemnity','claim arises','Amazon''s direction','specific material','ProdCo objected','writing','prior to inclusion','sole basis','claim','exclusion','not apply']::text[], '{"doc": "Counterparty_Markup", "section": "Amazon Indemnification", "note": "Written objection exception", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Exception for material ProdCo objected to in writing is fair if narrowly applied. ''Sole basis'' requirement prevents abuse. Incentivizes ProdCo to document objections."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon''s indemnification excludes production and content claims. The parties agree to maintain records of any instances where Amazon directs inclusion of specific material over ProdCo''s documented clearance concerns, and such matters shall be addressed separately if claims arise.', ARRAY['Amazon''s indemnification','excludes','production','content claims','maintain records','Amazon directs','specific material','documented clearance concerns','addressed separately','claims arise']::text[], '{"doc": "Counterparty_Markup", "section": "Amazon Indemnification", "note": "Record-keeping for directed content", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Record-keeping for Amazon-directed content over clearance concerns provides documentation without automatically shifting liability. ''Addressed separately'' preserves flexibility."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon''s indemnity excludes content claims. If Amazon supplies materials for inclusion in the Program (as documented per Section [X]), claims arising solely from such Amazon-supplied materials shall not be subject to this exclusion.', ARRAY['Amazon''s indemnity','excludes','content claims','Amazon supplies','materials','inclusion','documented','claims','solely','Amazon-supplied materials','not subject','exclusion']::text[], '{"doc": "Counterparty_Markup", "section": "Amazon Indemnification", "note": "Amazon-supplied materials exception", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Exception for claims arising solely from documented Amazon-supplied materials is appropriate reciprocal to ProdCo''s rep exception for Amazon-supplied materials."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Exclusions from Amazon indemnification include all content and production claims. The exclusions shall not apply to claims arising from Amazon''s willful misconduct in connection with exploitation of the Program, which shall be subject to Amazon''s indemnification regardless of claim type.', ARRAY['Exclusions','Amazon indemnification','content','production claims','not apply','claims','Amazon''s willful misconduct','exploitation','Program','subject to','indemnification','regardless','claim type']::text[], '{"doc": "Counterparty_Markup", "section": "Amazon Indemnification", "note": "Willful misconduct override", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Willful misconduct override of exclusions is reasonable. Amazon shouldn''t benefit from exclusions if claims arise from Amazon''s intentional wrongdoing."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon''s indemnification exclusions shall not apply if Amazon approved the content giving rise to the claim. Amazon''s approval of any content, script, or Material shall constitute Amazon''s assumption of responsibility for claims arising therefrom.', ARRAY['Amazon''s indemnification','exclusions','not apply','Amazon approved','content','claim','Amazon''s approval','content','script','Material','assumption of responsibility','claims']::text[], '{"doc": "Counterparty_Markup", "section": "Amazon Indemnification", "note": "Approval as responsibility assumption", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Amazon approval does not shift content responsibility. Amazon approves for its own purposes; content clearance remains ProdCo''s obligation. This would gut all exclusions."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Exclusions from Amazon''s indemnity apply only to claims that ProdCo could reasonably have prevented through its clearance processes. Claims arising from sophisticated or latent issues that ProdCo could not reasonably have identified shall be Amazon''s responsibility.', ARRAY['Exclusions','Amazon''s indemnity','only','claims','ProdCo could reasonably have prevented','clearance','sophisticated','latent issues','not reasonably identified','Amazon''s responsibility']::text[], '{"doc": "Counterparty_Markup", "section": "Amazon Indemnification", "note": "Reasonableness override of exclusions", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "''Could not reasonably have identified'' exception is impossible to administer and shifts difficult claims to Amazon. ProdCo is responsible for clearance regardless of difficulty."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon''s exclusions shall not apply to claims arising in territories where Amazon''s exploitation extends beyond ProdCo''s clearance scope. ProdCo''s clearance is limited to territories expressly identified in Exhibit A; claims from other territories are Amazon''s responsibility.', ARRAY['Amazon''s exclusions','not apply','claims','territories','exploitation extends beyond','clearance scope','ProdCo''s clearance','limited','territories','Exhibit A','other territories','Amazon''s responsibility']::text[], '{"doc": "Counterparty_Markup", "section": "Amazon Indemnification", "note": "Territorial clearance limitation", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "ProdCo clears for worldwide exploitation. Attempting to limit clearance to scheduled territories and shift remaining territory risk to Amazon is unacceptable."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon''s indemnity exclusions are subject to ProdCo''s compliance with all clearance best practices. If ProdCo has complied with industry-standard clearance procedures, any claim arising despite such compliance shall be excluded from ProdCo''s indemnity and included in Amazon''s indemnity.', ARRAY['Amazon''s indemnity exclusions','subject to','ProdCo''s compliance','clearance best practices','complied','industry-standard','clearance procedures','claim','despite compliance','excluded','ProdCo''s indemnity','included','Amazon''s indemnity']::text[], '{"doc": "Counterparty_Markup", "section": "Amazon Indemnification", "note": "Best practices compliance shift", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Compliance with clearance procedures doesn''t eliminate ProdCo''s content liability. Claims can arise from proper clearance; ProdCo still represents and warrants non-infringement."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon''s exclusions for content claims shall sunset three (3) years after initial release. After such period, content claims shall be Amazon''s responsibility as the ongoing exploiter of the Program with continuing benefit from exploitation.', ARRAY['Amazon''s exclusions','content claims','sunset','three years','initial release','after period','content claims','Amazon''s responsibility','ongoing exploiter','continuing benefit','exploitation']::text[], '{"doc": "Counterparty_Markup", "section": "Amazon Indemnification", "note": "Time-limited exclusions", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Content exclusions cannot sunset. Content liability persists throughout exploitation regardless of time. Three-year limit would shift perpetual content risk to Amazon."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Exclusions from Amazon''s indemnity shall be proportionate. If a claim involves both excluded content issues and non-excluded Amazon conduct issues, exclusions shall apply only to the portion of the claim attributable to content, with Amazon indemnifying for the remainder.', ARRAY['Exclusions','Amazon''s indemnity','proportionate','claim','excluded content issues','non-excluded','Amazon conduct','exclusions apply','portion','attributable to content','Amazon indemnifying','remainder']::text[], '{"doc": "Counterparty_Markup", "section": "Amazon Indemnification", "note": "Proportionate exclusions", "approval": null, "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "Proportionate exclusions create complex allocation disputes for every claim. Content exclusions should be categorical, not proportional. This invites litigation over allocation."}'::jsonb)
    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'To receive Amazon indemnification, ProdCo shall: (a) provide Amazon with prompt written notice of any claim; (b) grant Amazon sole control of the defense and settlement of such claim; (c) cooperate fully with Amazon''s defense at Amazon''s expense; and (d) not make any admission or settlement without Amazon''s prior written consent.', ARRAY['Amazon indemnification','ProdCo','prompt written notice','claim','grant Amazon','sole control','defense','settlement','cooperate fully','Amazon''s expense','no admission','settlement','prior written consent']::text[], '{"doc": "PSA_Fallbacks", "section": "Amazon Indemnification", "note": "Standard indemnification procedures", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Standard indemnification procedures including notice, Amazon control of defense/settlement, cooperation, and no unauthorized admissions/settlements. Appropriate for Amazon-controlled claims."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo''s right to Amazon indemnification is conditioned upon: (i) ProdCo providing notice to Amazon within ten (10) business days of receiving any claim; (ii) ProdCo not taking any position adverse to Amazon''s interests; (iii) ProdCo providing Amazon with all relevant information and documents; and (iv) ProdCo cooperating with Amazon''s selected counsel.', ARRAY['right to','Amazon indemnification','conditioned','notice','ten business days','receiving claim','not taking position','adverse','Amazon''s interests','relevant information','documents','cooperating','Amazon''s counsel']::text[], '{"doc": "PSA_Fallbacks", "section": "Amazon Indemnification", "note": "Notice timeline and conditions", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Ten-day notice requirement and enumerated conditions are clear and reasonable. Adverse position prohibition and document production requirements are standard."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon shall have the right to control the defense and settlement of any claim for which Amazon provides indemnification. Amazon may select counsel, determine strategy, and settle claims in Amazon''s sole discretion. ProdCo shall not interfere with or obstruct Amazon''s defense.', ARRAY['Amazon','control','defense','settlement','claim','indemnification','select counsel','determine strategy','settle','sole discretion','ProdCo','not interfere','obstruct','defense']::text[], '{"doc": "PSA_Fallbacks", "section": "Amazon Indemnification", "note": "Amazon defense control", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Amazon''s control over defense and settlement of indemnified claims is appropriate. Indemnifying party should control defense to manage exposure. ProdCo non-interference is standard."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Failure to provide timely notice of a claim shall not relieve Amazon of its indemnification obligation except to the extent Amazon is actually prejudiced by such failure. ProdCo shall bear the burden of demonstrating that Amazon was not prejudiced by late notice.', ARRAY['Failure','timely notice','not relieve','Amazon','indemnification','except','actually prejudiced','failure','ProdCo','burden','demonstrating','not prejudiced','late notice']::text[], '{"doc": "PSA_Fallbacks", "section": "Amazon Indemnification", "note": "Prejudice-based notice failure", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Prejudice-based notice failure standard with burden on ProdCo is balanced approach. Protects Amazon from late notice harm while not requiring forfeiture for minor delays."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo shall cooperate with Amazon''s defense of any indemnified claim, including making personnel available for depositions and testimony, providing documents and information, and assisting with factual investigation. Amazon shall reimburse ProdCo''s reasonable out-of-pocket costs for such cooperation.', ARRAY['cooperate','Amazon''s defense','indemnified claim','personnel','depositions','testimony','documents','information','factual investigation','reimburse','reasonable','out-of-pocket costs','cooperation']::text[], '{"doc": "PSA_Fallbacks", "section": "Amazon Indemnification", "note": "Cooperation with cost reimbursement", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Detailed cooperation requirements with cost reimbursement is fair. ProdCo assists defense; Amazon covers ProdCo''s cooperation costs."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon may settle any indemnified claim without ProdCo''s consent, provided that any settlement that includes an admission of liability by ProdCo or imposes any ongoing obligation on ProdCo shall require ProdCo''s prior written consent, which shall not be unreasonably withheld.', ARRAY['Amazon','settle','indemnified claim','without','ProdCo''s consent','provided','settlement','admission of liability','ProdCo','ongoing obligation','require','prior written consent','not unreasonably withheld']::text[], '{"doc": "PSA_Fallbacks", "section": "Amazon Indemnification", "note": "Settlement with ProdCo admission/obligation consent", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Amazon settlement discretion with consent requirement for ProdCo admissions or ongoing obligations is balanced. Protects ProdCo from settlements affecting its interests."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Written notice to Amazon shall include: (a) a copy of the claim or demand; (b) a description of the facts underlying the claim; (c) ProdCo''s assessment of the claim''s relationship to Amazon''s indemnification obligations; and (d) any other relevant information in ProdCo''s possession.', ARRAY['Written notice','Amazon','copy','claim','demand','description','facts','ProdCo''s assessment','relationship','Amazon''s indemnification','relevant information','possession']::text[], '{"doc": "PSA_Fallbacks", "section": "Amazon Indemnification", "note": "Notice content requirements", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Notice content requirements ensure Amazon receives sufficient information to evaluate and respond to claims. ProdCo assessment requirement aids initial evaluation."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo shall provide prompt notice of claims. Amazon shall notify ProdCo within fifteen (15) business days whether Amazon will assume defense of the claim. If Amazon does not assume defense, ProdCo may defend with counsel of its choosing at Amazon''s expense.', ARRAY['prompt notice','claims','Amazon notify','ProdCo','fifteen business days','assume defense','Amazon does not assume','ProdCo may defend','counsel','choosing','Amazon''s expense']::text[], '{"doc": "Counterparty_Markup", "section": "Amazon Indemnification", "note": "Defense assumption timeline", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Fifteen-day window for Amazon''s defense assumption decision is reasonable. ProdCo''s right to defend if Amazon doesn''t assume is fair given Amazon''s indemnification obligation."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon controls defense of indemnified claims. ProdCo shall have the right to participate in the defense at its own expense with counsel of its choosing, provided that ProdCo''s participation shall not interfere with Amazon''s control of the defense or settlement.', ARRAY['Amazon controls','defense','indemnified claims','ProdCo','right to participate','own expense','counsel','choosing','not interfere','Amazon''s control','defense','settlement']::text[], '{"doc": "Counterparty_Markup", "section": "Amazon Indemnification", "note": "ProdCo participation right", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "ProdCo''s participation right at own expense without interfering with Amazon''s control is reasonable. Allows ProdCo visibility into defense without undermining Amazon''s management."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon shall keep ProdCo reasonably informed of the status of any indemnified claim, including significant developments, settlement discussions, and strategic decisions. ProdCo''s input shall be considered in good faith but Amazon shall retain final decision-making authority.', ARRAY['Amazon','keep ProdCo','reasonably informed','status','indemnified claim','significant developments','settlement discussions','strategic decisions','ProdCo''s input','considered','good faith','Amazon','final decision-making authority']::text[], '{"doc": "Counterparty_Markup", "section": "Amazon Indemnification", "note": "Information and input rights", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Information rights and good faith consideration of ProdCo input are reasonable additions that don''t undermine Amazon''s control. Final authority remains with Amazon."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo shall provide notice of claims within thirty (30) days of receipt. Failure to provide notice within such period shall reduce Amazon''s indemnification obligation by the amount of any losses or costs that Amazon demonstrates would have been avoided with timely notice.', ARRAY['notice','claims','thirty days','receipt','failure','notice','reduce','Amazon''s indemnification','amount','losses','costs','Amazon demonstrates','avoided','timely notice']::text[], '{"doc": "Counterparty_Markup", "section": "Amazon Indemnification", "note": "Proportionate reduction for late notice", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Proportionate reduction for late notice based on demonstrated avoidable losses is fair compared to full forfeiture. Thirty-day window is reasonable."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon may settle claims in its discretion. If Amazon proposes to settle a claim on terms that would require ProdCo to cease any activity or admit any wrongdoing, Amazon shall consult with ProdCo prior to accepting such settlement, and ProdCo may reject such settlement if the proposed terms are unreasonable.', ARRAY['Amazon','settle','discretion','proposes','settlement','require ProdCo','cease activity','admit wrongdoing','consult','ProdCo','prior to accepting','ProdCo may reject','terms','unreasonable']::text[], '{"doc": "Counterparty_Markup", "section": "Amazon Indemnification", "note": "Settlement with activity/admission consultation", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Consultation and rejection right for settlements affecting ProdCo''s activities or requiring admissions is fair protection. ''Unreasonable'' standard provides objective measure."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'The parties shall cooperate on indemnification procedures. If a claim appears to involve both Amazon indemnification and ProdCo indemnification triggers, the parties shall consult in good faith to coordinate defense and allocate costs appropriately pending resolution of coverage issues.', ARRAY['cooperate','indemnification procedures','claim','involves','Amazon indemnification','ProdCo indemnification','triggers','consult','good faith','coordinate defense','allocate costs','pending resolution','coverage issues']::text[], '{"doc": "Counterparty_Markup", "section": "Amazon Indemnification", "note": "Mixed-claim coordination", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Coordination mechanism for claims with mixed indemnification triggers is practical. Good faith allocation pending resolution addresses common real-world scenario."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall have the right to control the defense of any claim for which ProdCo seeks Amazon indemnification. ProdCo shall select counsel and determine strategy, and Amazon shall reimburse ProdCo''s costs. Amazon may not assume defense over ProdCo''s objection.', ARRAY['ProdCo','right to control','defense','claim','seeks Amazon indemnification','select counsel','determine strategy','Amazon reimburse','costs','Amazon may not','assume defense','ProdCo''s objection']::text[], '{"doc": "Counterparty_Proposal", "section": "Amazon Indemnification", "note": "ProdCo defense control", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "ProdCo cannot control defense of Amazon-indemnified claims. Indemnifying party (Amazon) must control defense to manage its exposure. This inverts proper indemnification structure."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon shall not settle any indemnified claim without ProdCo''s prior written consent, which consent may be withheld in ProdCo''s sole discretion for any reason.', ARRAY['Amazon','not settle','indemnified claim','without','ProdCo''s prior written consent','withheld','ProdCo''s sole discretion','any reason']::text[], '{"doc": "Counterparty_Proposal", "section": "Amazon Indemnification", "note": "ProdCo settlement veto", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "ProdCo veto over settlement in ''sole discretion for any reason'' gives ProdCo inappropriate control over Amazon''s exposure. Amazon needs settlement discretion for claims it indemnifies."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall provide notice of claims when practicable. Failure to provide timely notice shall not affect Amazon''s indemnification obligation under any circumstances, as ProdCo should not lose coverage for administrative lapses.', ARRAY['notice','claims','when practicable','failure','timely notice','not affect','Amazon''s indemnification','any circumstances','not lose coverage','administrative lapses']::text[], '{"doc": "Counterparty_Proposal", "section": "Amazon Indemnification", "note": "No notice consequence", "approval": null, "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "Eliminating all consequences for notice failure removes Amazon''s ability to protect itself. Timely notice is essential for proper defense. Some consequence for failure is required."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon shall respond to indemnification requests within five (5) business days. Failure to respond shall constitute acceptance of the indemnification request and assumption of all related costs and defense obligations.', ARRAY['Amazon','respond','indemnification requests','five business days','failure to respond','constitute acceptance','indemnification request','assumption','all related costs','defense obligations']::text[], '{"doc": "Counterparty_Proposal", "section": "Amazon Indemnification", "note": "Deemed acceptance for non-response", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Five-day deemed acceptance is unreasonable. Amazon needs adequate time to evaluate claims. Deemed acceptance for non-response could create liability for non-indemnifiable claims."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo may settle any claim for which Amazon indemnification is sought without Amazon''s consent if the settlement amount is less than $100,000. Amazon shall reimburse such settlements promptly upon ProdCo''s request with documentation.', ARRAY['ProdCo may settle','claim','Amazon indemnification','without','Amazon''s consent','settlement amount','less than $100,000','Amazon reimburse','settlements','promptly','request','documentation']::text[], '{"doc": "Counterparty_Proposal", "section": "Amazon Indemnification", "note": "ProdCo settlement without consent below threshold", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "ProdCo settlement authority without consent removes Amazon''s control over its indemnification exposure. Amazon cannot be forced to reimburse settlements it didn''t approve."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon''s indemnification obligation shall be triggered upon ProdCo''s assertion that a claim falls within Amazon''s indemnification scope. Amazon may not dispute such assertion except through binding arbitration, and Amazon shall fund defense pending arbitration resolution.', ARRAY['Amazon''s indemnification','triggered','ProdCo''s assertion','claim','indemnification scope','Amazon may not dispute','except','binding arbitration','fund defense','pending','arbitration resolution']::text[], '{"doc": "Counterparty_Proposal", "section": "Amazon Indemnification", "note": "ProdCo-triggered indemnification", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "ProdCo''s unilateral assertion triggering indemnification with Amazon funding pending arbitration completely inverts proper indemnification structure. Amazon must determine if claims are indemnifiable."}'::jsonb)
    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon''s aggregate liability under this indemnification provision shall not exceed the total fees actually paid by Amazon to ProdCo under this Agreement. This limitation shall not apply to Amazon''s fraud or willful misconduct.', ARRAY['Amazon''s aggregate liability','indemnification','not exceed','total fees','actually paid','Amazon','ProdCo','limitation','not apply','Amazon''s fraud','willful misconduct']::text[], '{"doc": "PSA_Fallbacks", "section": "Amazon Indemnification", "note": "Fees-paid cap with fraud/willful misconduct exception", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Cap at fees paid is reasonable limitation on Amazon''s exposure. Fraud/willful misconduct exception preserves accountability for serious conduct. Standard commercial limitation."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon''s indemnification liability shall be subject to an aggregate cap of [specified amount]. This cap shall apply to all claims in the aggregate, not per claim. Claims arising from Amazon''s gross negligence or willful misconduct shall not be subject to this cap.', ARRAY['Amazon''s indemnification','liability','aggregate cap','specified amount','all claims','aggregate','not per claim','claims','gross negligence','willful misconduct','not subject to','cap']::text[], '{"doc": "PSA_Fallbacks", "section": "Amazon Indemnification", "note": "Fixed aggregate cap", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Fixed aggregate cap with gross negligence/willful misconduct exception is appropriate limitation. Aggregate (not per-claim) basis provides predictable exposure limit."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon''s liability under the indemnification provisions shall be limited to direct damages and shall not include consequential, incidental, special, punitive or exemplary damages, lost profits, or loss of business opportunity, regardless of whether such damages were foreseeable.', ARRAY['Amazon''s liability','indemnification','limited','direct damages','not include','consequential','incidental','special','punitive','exemplary','lost profits','loss of business opportunity','regardless','foreseeable']::text[], '{"doc": "PSA_Fallbacks", "section": "Amazon Indemnification", "note": "Consequential damages exclusion", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Consequential damages exclusion is standard commercial limitation. Direct damages limitation provides reasonable protection while covering actual third-party claim costs."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Any liability cap on Amazon''s indemnification shall not apply to: (a) claims arising from Amazon''s breach of confidentiality; (b) claims arising from Amazon''s violation of applicable law; (c) Amazon''s fraud; or (d) Amazon''s willful misconduct.', ARRAY['liability cap','Amazon''s indemnification','not apply','claims','breach of confidentiality','violation','applicable law','fraud','willful misconduct']::text[], '{"doc": "PSA_Fallbacks", "section": "Amazon Indemnification", "note": "Super-cap exceptions", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Exceptions to cap for confidentiality breach, legal violations, fraud, and willful misconduct are standard commercial terms that preserve accountability for serious matters."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon''s total liability to ProdCo under this Agreement, including under the indemnification provisions, shall not exceed [2x/3x] the Production Fee. This limitation applies to all claims arising under or relating to this Agreement in the aggregate.', ARRAY['Amazon''s total liability','ProdCo','Agreement','including','indemnification','not exceed','2x/3x','Production Fee','limitation','all claims','aggregate']::text[], '{"doc": "PSA_Fallbacks", "section": "Amazon Indemnification", "note": "Multiple of Production Fee cap", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Cap at multiple of Production Fee provides reasonable ceiling tied to deal economics. Applies to all claims, providing comprehensive limitation."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon''s indemnification liability shall be reduced by amounts recovered by ProdCo from insurance or other sources. ProdCo shall use commercially reasonable efforts to pursue available insurance coverage before seeking payment from Amazon under this indemnification.', ARRAY['Amazon''s indemnification','liability','reduced','amounts recovered','ProdCo','insurance','other sources','commercially reasonable efforts','pursue','insurance coverage','before seeking','payment','Amazon']::text[], '{"doc": "PSA_Fallbacks", "section": "Amazon Indemnification", "note": "Insurance offset", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Insurance offset reduces Amazon''s exposure and requires ProdCo to pursue available coverage. Prevents double recovery while ensuring ProdCo is made whole."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon''s liability for indemnified claims shall be subject to an annual cap equal to the lesser of (a) the total fees paid in the applicable contract year, or (b) $[amount]. This cap resets annually on the anniversary of the Effective Date.', ARRAY['Amazon''s liability','indemnified claims','annual cap','lesser of','total fees','applicable contract year','amount','cap resets','annually','anniversary','Effective Date']::text[], '{"doc": "PSA_Fallbacks", "section": "Amazon Indemnification", "note": "Annual resetting cap", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Annual resetting cap provides ongoing protection while limiting single-year exposure. Appropriate for multi-year or series deals."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon''s indemnification liability shall be capped at the greater of (a) the total fees paid to ProdCo, or (b) $1,000,000. This cap shall not apply to fraud, willful misconduct, or breach of Amazon''s representations regarding authority.', ARRAY['Amazon''s indemnification','liability','capped','greater of','total fees','$1,000,000','cap','not apply','fraud','willful misconduct','breach','representations','authority']::text[], '{"doc": "Counterparty_Markup", "section": "Amazon Indemnification", "note": "Greater-of cap with floor", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Floor amount ($1M) ensures minimum coverage regardless of fee level. ''Greater of'' formula benefits ProdCo for larger deals. Exceptions are standard."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon''s indemnification cap applies to monetary damages only. Equitable relief, including specific performance and injunctive relief, shall be available to ProdCo without regard to any cap, if ProdCo demonstrates irreparable harm.', ARRAY['Amazon''s indemnification','cap','monetary damages only','equitable relief','specific performance','injunctive relief','available','without regard to','cap','irreparable harm']::text[], '{"doc": "Counterparty_Markup", "section": "Amazon Indemnification", "note": "Equitable relief exception to cap", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Carving equitable relief from cap is standard commercial approach. Doesn''t expand monetary exposure but preserves non-monetary remedies."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon''s liability is capped as set forth in this Agreement. The cap shall be adjusted upward by 10% for each full year following the Effective Date to account for inflation, not to exceed 150% of the original cap amount.', ARRAY['Amazon''s liability','capped','adjusted upward','10%','each full year','Effective Date','account for inflation','not to exceed','150%','original cap amount']::text[], '{"doc": "Counterparty_Markup", "section": "Amazon Indemnification", "note": "Inflation adjustment to cap", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Inflation adjustment to cap is reasonable for long-term deals. 150% ceiling provides predictability while addressing real-value erosion."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon''s aggregate indemnification liability is capped. If multiple Amazon entities are named in a claim, the cap shall apply to all Amazon entities collectively, not separately to each entity. Joint and several claims shall be subject to a single cap.', ARRAY['Amazon''s aggregate','indemnification','liability','capped','multiple Amazon entities','claim','cap','collectively','not separately','joint and several','single cap']::text[], '{"doc": "Counterparty_Markup", "section": "Amazon Indemnification", "note": "Multi-entity cap clarification", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Clarification that cap applies collectively to all Amazon entities prevents stacking of caps. Single cap for joint claims is appropriate."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon''s indemnification liability shall be capped at the Production Fee. If the claim arises from conduct occurring after final delivery, the cap shall be the greater of (a) the Production Fee, or (b) twelve (12) months of exploitation revenue attributable to the Program.', ARRAY['Amazon''s indemnification','capped','Production Fee','claim arises','after final delivery','cap','greater of','Production Fee','twelve months','exploitation revenue','attributable','Program']::text[], '{"doc": "Counterparty_Markup", "section": "Amazon Indemnification", "note": "Revenue-based cap for post-delivery claims", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Revenue-based alternative cap for post-delivery claims acknowledges ongoing exploitation value. Provides additional coverage for exploitation-phase issues."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon''s indemnification shall be subject to an aggregate cap. The cap shall not reduce amounts payable for defense costs; Amazon shall pay reasonable defense costs in addition to any capped liability for judgments or settlements.', ARRAY['Amazon''s indemnification','aggregate cap','cap','not reduce','defense costs','Amazon','pay','reasonable defense costs','addition to','capped liability','judgments','settlements']::text[], '{"doc": "Counterparty_Markup", "section": "Amazon Indemnification", "note": "Defense costs outside cap", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Defense costs outside cap is common approach that ensures ProdCo can mount adequate defense regardless of ultimate liability outcome. May be acceptable depending on cap amount."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon''s indemnification shall be uncapped and unlimited. Amazon shall be liable for all losses, costs, and expenses arising from any indemnified claim without any limitation.', ARRAY['Amazon''s indemnification','uncapped','unlimited','Amazon','liable','all losses','costs','expenses','indemnified claim','without','limitation']::text[], '{"doc": "Counterparty_Proposal", "section": "Amazon Indemnification", "note": "Uncapped Amazon indemnity", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Uncapped Amazon indemnity creates unlimited exposure. Amazon''s indemnity scope is already narrow; reasonable cap is appropriate additional protection."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon''s indemnification cap shall be no less than ProdCo''s indemnification cap (if any). If ProdCo''s indemnification is uncapped, Amazon''s indemnification shall also be uncapped to maintain parity.', ARRAY['Amazon''s indemnification','cap','no less than','ProdCo''s indemnification cap','ProdCo''s indemnification','uncapped','Amazon''s indemnification','uncapped','maintain parity']::text[], '{"doc": "Counterparty_Proposal", "section": "Amazon Indemnification", "note": "Forced cap parity", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Forced parity ignores fundamental asymmetry. ProdCo''s content indemnity is appropriately uncapped; Amazon''s narrow indemnity appropriately has caps. Different scopes justify different limits."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon''s indemnification cap shall be equal to the total revenue generated by Amazon from exploitation of the Program. The cap shall increase as exploitation revenue increases.', ARRAY['Amazon''s indemnification','cap','equal to','total revenue','generated','Amazon','exploitation','Program','cap','increase','exploitation revenue increases']::text[], '{"doc": "Counterparty_Proposal", "section": "Amazon Indemnification", "note": "Revenue-based expanding cap", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Revenue-based cap with unlimited upside creates unpredictable, potentially massive exposure. Cap must be fixed or tied to fees paid, not exploitation revenue."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon''s cap shall not apply to any claim that ProdCo asserts arises from Amazon''s breach. ProdCo''s good faith assertion that a claim is uncapped shall be dispositive unless Amazon proves such assertion was made in bad faith.', ARRAY['Amazon''s cap','not apply','claim','ProdCo asserts','arises from','Amazon''s breach','good faith assertion','uncapped','dispositive','unless','Amazon proves','bad faith']::text[], '{"doc": "Counterparty_Proposal", "section": "Amazon Indemnification", "note": "ProdCo-controlled cap exception", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "ProdCo''s assertion eliminating cap unless Amazon proves bad faith gives ProdCo effective control over cap application. Completely undermines cap protection."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon''s indemnification cap applies only to the first claim asserted. Subsequent claims shall be uncapped, as a pattern of claims suggests systemic issues requiring Amazon accountability.', ARRAY['Amazon''s indemnification','cap','only','first claim','subsequent claims','uncapped','pattern of claims','systemic issues','Amazon accountability']::text[], '{"doc": "Counterparty_Proposal", "section": "Amazon Indemnification", "note": "First-claim-only cap", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Limiting cap to first claim creates unlimited exposure for subsequent claims. Multiple claims could arise from single issue (multiple territories, claimants). Cap must apply to all claims."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon''s liability cap shall not include attorneys'' fees, defense costs, investigation expenses, or other litigation-related costs. Such costs shall be payable by Amazon without limit in addition to the capped damages.', ARRAY['Amazon''s liability cap','not include','attorneys'' fees','defense costs','investigation expenses','litigation-related costs','payable','Amazon','without limit','addition to','capped damages']::text[], '{"doc": "Counterparty_Proposal", "section": "Amazon Indemnification", "note": "Unlimited costs outside cap", "approval": null, "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "Unlimited costs outside cap could result in defense costs exceeding cap amount, potentially by multiples. Some cost limitation is needed for predictable exposure."}'::jsonb)
    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'IN NO EVENT SHALL AMAZON BE LIABLE TO PRODCO FOR ANY CONSEQUENTIAL, INDIRECT, INCIDENTAL, SPECIAL, PUNITIVE OR EXEMPLARY DAMAGES, INCLUDING WITHOUT LIMITATION LOST PROFITS, LOSS OF BUSINESS, LOSS OF GOODWILL, OR LOSS OF DATA, ARISING OUT OF OR RELATING TO THIS AGREEMENT, REGARDLESS OF THE THEORY OF LIABILITY.', ARRAY['Amazon','not liable','consequential','indirect','incidental','special','punitive','exemplary damages','lost profits','loss of business','goodwill','loss of data','regardless','theory of liability']::text[], '{"doc": "PSA_Principal_Terms", "section": "Limitation of Liability", "note": "Standard Amazon consequential damages exclusion", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Standard comprehensive exclusion of consequential and similar damages. Caps style formatting emphasizes importance. Covers key categories including lost profits and business losses."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon shall not be liable for any indirect, consequential, special, incidental or punitive damages of any kind, whether arising in contract, tort (including negligence), strict liability, or otherwise, even if Amazon has been advised of the possibility of such damages.', ARRAY['Amazon','not liable','indirect','consequential','special','incidental','punitive damages','contract','tort','negligence','strict liability','advised of possibility']::text[], '{"doc": "PSA_Principal_Terms", "section": "Limitation of Liability", "note": "Multi-theory coverage with foreseeability waiver", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Covers all liability theories (contract, tort, strict liability) and includes ''advised of possibility'' language to negate foreseeability-based claims."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Notwithstanding anything to the contrary in this Agreement, Amazon''s liability shall be limited to direct damages only. Amazon expressly disclaims and excludes all liability for consequential damages, special damages, punitive damages, incidental damages, indirect damages, lost revenues, lost profits, and damages for loss of use, business interruption, or loss of information or data.', ARRAY['Amazon''s liability','limited','direct damages only','disclaims','excludes','consequential','special','punitive','incidental','indirect','lost revenues','lost profits','loss of use','business interruption','loss of information','data']::text[], '{"doc": "PSA_Principal_Terms", "section": "Limitation of Liability", "note": "Direct damages limitation with comprehensive exclusion list", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Affirmatively limits to direct damages while comprehensively listing excluded damage types. Business interruption and data loss explicitly covered."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon shall have no liability for any consequential, indirect, incidental, special, exemplary or punitive damages, including damages for loss of profits, goodwill, use, data or other intangible losses, even if Amazon has been advised of the possibility of such damages. This exclusion applies to the maximum extent permitted by applicable law.', ARRAY['Amazon','no liability','consequential','indirect','incidental','special','exemplary','punitive','loss of profits','goodwill','use','data','intangible losses','advised of possibility','maximum extent','applicable law']::text[], '{"doc": "PSA_Principal_Terms", "section": "Limitation of Liability", "note": "Intangible losses with maximum extent language", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Includes intangible losses and ''maximum extent permitted by law'' language for jurisdictions with mandatory liability provisions."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'The exclusion of consequential damages set forth herein shall apply regardless of: (a) the form of action, whether in contract, warranty, tort, negligence, strict liability, or otherwise; (b) whether the damages were foreseeable; (c) whether Amazon was advised of the possibility of such damages; or (d) whether the limited remedy provided herein fails of its essential purpose.', ARRAY['exclusion','consequential damages','apply regardless of','form of action','contract','warranty','tort','negligence','strict liability','foreseeable','advised of possibility','limited remedy','fails','essential purpose']::text[], '{"doc": "PSA_Principal_Terms", "section": "Limitation of Liability", "note": "Comprehensive applicability language", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Addresses key legal doctrines that could otherwise circumvent exclusion: theory of liability, foreseeability, notice, and failure of essential purpose."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo acknowledges and agrees that the exclusion of consequential and other damages set forth herein is an essential element of the bargain between the parties, and that the fees and other terms of this Agreement reflect this allocation of risk. Amazon would not enter into this Agreement without such exclusion.', ARRAY['acknowledges','agrees','exclusion','consequential','damages','essential element','bargain','fees','terms','allocation of risk','would not enter','without exclusion']::text[], '{"doc": "PSA_Principal_Terms", "section": "Limitation of Liability", "note": "Bargained-for acknowledgment", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "ProdCo acknowledgment that exclusion is bargained-for element reinforces enforceability and prevents unconscionability arguments."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'AMAZON EXCLUDES ALL LIABILITY FOR CONSEQUENTIAL, INDIRECT, SPECIAL, INCIDENTAL, AND PUNITIVE DAMAGES. For purposes of this exclusion, ''consequential damages'' includes, without limitation: lost profits; lost revenues; cost of substitute services; loss of data; loss of goodwill; business interruption; and any damages arising from third-party claims against ProdCo.', ARRAY['Amazon excludes','liability','consequential','indirect','special','incidental','punitive','consequential damages includes','lost profits','revenues','substitute services','loss of data','goodwill','business interruption','third-party claims']::text[], '{"doc": "PSA_Principal_Terms", "section": "Limitation of Liability", "note": "Defined consequential damages", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Defines ''consequential damages'' to include specific categories, preventing disputes about what falls within the exclusion."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon excludes liability for consequential, indirect, and punitive damages. This exclusion shall not apply to damages arising from Amazon''s fraud, willful misconduct, or gross negligence, for which Amazon shall remain liable under applicable law.', ARRAY['Amazon excludes','liability','consequential','indirect','punitive','exclusion','not apply','Amazon''s fraud','willful misconduct','gross negligence','remain liable','applicable law']::text[], '{"doc": "Counterparty_Markup", "section": "Limitation of Liability", "note": "Fraud/willful misconduct/gross negligence exception", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Exceptions for fraud, willful misconduct, and gross negligence are common and generally acceptable. May be required in some jurisdictions anyway."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon excludes consequential and indirect damages. Notwithstanding the foregoing, this exclusion shall not apply to damages arising from Amazon''s breach of its payment obligations, which shall be recoverable as direct damages without limitation.', ARRAY['Amazon excludes','consequential','indirect','notwithstanding','exclusion','not apply','Amazon''s breach','payment obligations','recoverable','direct damages','without limitation']::text[], '{"doc": "Counterparty_Markup", "section": "Limitation of Liability", "note": "Payment breach exception", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Payment breach exception is reasonable\u2014failure to pay is a direct breach with direct damages. Doesn''t actually expand consequential damages exposure."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Each party excludes liability to the other for consequential, indirect, incidental, special, and punitive damages. This mutual exclusion applies equally to both parties and shall survive termination of this Agreement.', ARRAY['each party','excludes liability','other','consequential','indirect','incidental','special','punitive','mutual exclusion','equally','both parties','survive termination']::text[], '{"doc": "Counterparty_Markup", "section": "Limitation of Liability", "note": "Mutual consequential damages exclusion", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Mutual exclusion is acceptable as Amazon also benefits. Key is ensuring ProdCo''s indemnification obligations are not affected by this exclusion."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon excludes consequential damages liability. This exclusion shall not apply to consequential damages that are the direct and proximate result of Amazon''s material breach of this Agreement and that were reasonably foreseeable at the time of contracting.', ARRAY['Amazon excludes','consequential damages','exclusion','not apply','direct','proximate result','Amazon''s material breach','reasonably foreseeable','time of contracting']::text[], '{"doc": "Counterparty_Markup", "section": "Limitation of Liability", "note": "Material breach with foreseeability exception", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Material breach exception with foreseeability requirement is more limited than broad exception. Foreseeability at contracting time provides some predictability."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon excludes consequential and punitive damages. The parties acknowledge that certain statutory claims may not be subject to this exclusion under applicable law, and to the extent any such claim is not excludable, the exclusion shall not apply to such claim.', ARRAY['Amazon excludes','consequential','punitive','acknowledge','statutory claims','not subject to','exclusion','applicable law','not excludable','not apply']::text[], '{"doc": "Counterparty_Markup", "section": "Limitation of Liability", "note": "Statutory non-excludable claims acknowledgment", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Acknowledgment of statutory non-excludable claims is practical reality in some jurisdictions. Preserves exclusion to maximum extent permitted."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon''s consequential damages exclusion shall apply. However, if Amazon''s breach causes ProdCo to lose a specific, documented third-party opportunity that ProdCo can prove with reasonable certainty, such lost opportunity damages may be recoverable as direct damages up to [specified cap].', ARRAY['Amazon''s consequential','exclusion','apply','however','Amazon''s breach','causes','lose','specific','documented','third-party opportunity','prove','reasonable certainty','recoverable','direct damages','cap']::text[], '{"doc": "Counterparty_Markup", "section": "Limitation of Liability", "note": "Limited lost opportunity exception", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Limited, documented lost opportunity exception with cap may be acceptable. ''Specific, documented'' and ''reasonable certainty'' requirements limit exposure."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon excludes consequential damages liability, except that this exclusion shall not apply to any damages arising from Amazon''s failure to release the Program, Amazon''s early termination of the Agreement, or Amazon''s decision not to order additional seasons.', ARRAY['Amazon excludes','consequential','except','not apply','damages','Amazon''s failure','release','Program','early termination','decision','not order','additional seasons']::text[], '{"doc": "Counterparty_Markup", "section": "Limitation of Liability", "note": "Business decision exceptions", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Exceptions for non-release, termination, and season decisions would create massive exposure for Amazon''s core business discretion. These must be excluded."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Each party excludes consequential damages liability to the other. Notwithstanding the foregoing, this exclusion shall not affect ProdCo''s right to recover consequential damages for Amazon''s breach of any confidentiality, exclusivity, or credit obligations.', ARRAY['each party excludes','consequential damages','notwithstanding','not affect','ProdCo''s right','recover','consequential damages','Amazon''s breach','confidentiality','exclusivity','credit obligations']::text[], '{"doc": "Counterparty_Markup", "section": "Limitation of Liability", "note": "Specific obligation exceptions", "approval": null, "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "Carving out confidentiality, exclusivity, and credit obligations from exclusion creates significant unpredictable exposure for specific breach categories."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon''s consequential damages exclusion applies only to damages that ProdCo cannot prove with documentary evidence. Consequential damages that ProdCo can prove through financial records, contracts, or other documentation shall be recoverable.', ARRAY['Amazon''s consequential','exclusion','applies only','cannot prove','documentary evidence','damages','prove','financial records','contracts','documentation','recoverable']::text[], '{"doc": "Counterparty_Markup", "section": "Limitation of Liability", "note": "Documentary evidence exception", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Limiting exclusion to unprovable damages effectively eliminates the exclusion. Most consequential damages can be documented to some degree."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon excludes consequential damages. This exclusion is subject to an aggregate floor of $500,000; consequential damages up to $500,000 are recoverable despite the exclusion, with only damages exceeding such amount being excluded.', ARRAY['Amazon excludes','consequential damages','exclusion','subject to','aggregate floor','$500,000','recoverable','despite exclusion','exceeding','excluded']::text[], '{"doc": "Counterparty_Markup", "section": "Limitation of Liability", "note": "Dollar floor on exclusion", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Dollar floor effectively allows $500K in consequential damages, defeating purpose of exclusion. Exclusion must be absolute, not subject to minimums."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon''s consequential damages exclusion shall not apply if Amazon''s conduct giving rise to damages was unreasonable under the circumstances. ProdCo may recover consequential damages if Amazon acted unreasonably in breaching the Agreement.', ARRAY['Amazon''s consequential','exclusion','not apply','Amazon''s conduct','unreasonable','circumstances','ProdCo may recover','consequential damages','acted unreasonably','breaching']::text[], '{"doc": "Counterparty_Markup", "section": "Limitation of Liability", "note": "Unreasonableness exception", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "''Unreasonable'' exception is subjective and could apply to virtually any breach. Would require litigating reasonableness for every claim, defeating exclusion purpose."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Consequential damages are excluded. However, ''consequential damages'' shall be narrowly construed and shall not include lost profits, lost revenues, or loss of business opportunity, which are deemed direct damages for purposes of this Agreement.', ARRAY['consequential damages','excluded','narrowly construed','not include','lost profits','lost revenues','loss of business opportunity','deemed','direct damages']::text[], '{"doc": "Counterparty_Markup", "section": "Limitation of Liability", "note": "Recharacterization of consequential as direct", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Recharacterizing lost profits and revenues as ''direct damages'' completely guts the exclusion. These are classic consequential damages that must remain excluded."}'::jsonb)
    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'AMAZON''S TOTAL AGGREGATE LIABILITY ARISING OUT OF OR RELATING TO THIS AGREEMENT SHALL NOT EXCEED THE TOTAL FEES ACTUALLY PAID BY AMAZON TO PRODCO UNDER THIS AGREEMENT DURING THE TWELVE (12) MONTH PERIOD PRECEDING THE CLAIM.', ARRAY['Amazon''s total aggregate liability','arising out of','relating to','Agreement','not exceed','total fees','actually paid','Amazon','ProdCo','twelve month period','preceding claim']::text[], '{"doc": "PSA_Principal_Terms", "section": "Limitation of Liability", "note": "Standard fees-paid cap with lookback", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Standard cap at fees paid with 12-month lookback period. Caps format emphasizes importance. Lookback provides reasonable limitation for long-term agreements."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon''s maximum liability under this Agreement, whether arising in contract, tort, or otherwise, shall be limited to the aggregate amount of Production Fees paid by Amazon hereunder. This cap applies to all claims in the aggregate, not on a per-claim basis.', ARRAY['Amazon''s maximum liability','Agreement','contract','tort','otherwise','limited','aggregate amount','Production Fees','paid','cap applies','all claims','aggregate','not per-claim']::text[], '{"doc": "PSA_Principal_Terms", "section": "Limitation of Liability", "note": "All-theories cap with aggregate clarification", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Covers all liability theories with explicit aggregate (not per-claim) application. Production Fees reference ties cap to deal value."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'In no event shall Amazon''s liability to ProdCo exceed [specified dollar amount] in the aggregate for all claims arising under or relating to this Agreement. This limitation applies regardless of the number of claims, causes of action, or theories of recovery.', ARRAY['Amazon''s liability','not exceed','specified dollar amount','aggregate','all claims','arising under','relating to','limitation applies','regardless','number of claims','causes of action','theories']::text[], '{"doc": "PSA_Principal_Terms", "section": "Limitation of Liability", "note": "Fixed dollar cap", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Fixed dollar cap provides predictable exposure ceiling. Appropriate for deals where fee structure makes percentage cap impractical."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon''s total liability shall be capped at the greater of: (a) the Production Fee paid under this Agreement; or (b) $1,000,000. This cap shall not apply to Amazon''s payment obligations under Section [X] (Payment Terms).', ARRAY['Amazon''s total liability','capped','greater of','Production Fee','$1,000,000','cap','not apply','Amazon''s payment obligations','Payment Terms']::text[], '{"doc": "PSA_Principal_Terms", "section": "Limitation of Liability", "note": "Greater-of cap with payment carveout", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Greater-of formula ensures minimum cap regardless of fee level. Payment obligation carveout is standard\u2014cap shouldn''t limit contractual payment obligations."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon''s liability cap equals the fees paid hereunder. This cap does not apply to: (i) Amazon''s express payment obligations; (ii) amounts owed under Amazon''s indemnification obligations; or (iii) Amazon''s fraud or willful misconduct.', ARRAY['Amazon''s liability cap','equals','fees paid','cap does not apply','express payment obligations','amounts owed','indemnification obligations','fraud','willful misconduct']::text[], '{"doc": "PSA_Principal_Terms", "section": "Limitation of Liability", "note": "Standard carveouts from cap", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Standard carveouts for payments, indemnification, and fraud/willful misconduct. Appropriate exceptions that don''t undermine core liability protection."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'The liability cap herein reflects the parties'' agreed allocation of risk. ProdCo acknowledges that Amazon''s fees and other economic terms have been negotiated in light of this limitation, and that Amazon would not offer such terms absent this limitation.', ARRAY['liability cap','reflects','agreed allocation of risk','acknowledges','fees','economic terms','negotiated','in light of','limitation','would not offer','absent limitation']::text[], '{"doc": "PSA_Principal_Terms", "section": "Limitation of Liability", "note": "Risk allocation acknowledgment", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "ProdCo acknowledgment reinforces enforceability by establishing that cap was bargained-for and reflected in pricing."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'For series orders, Amazon''s liability cap shall be calculated on a per-season basis, with the cap for each season equal to the Production Fee paid for that season. Claims relating to multiple seasons shall be allocated proportionately.', ARRAY['series orders','Amazon''s liability cap','per-season basis','cap','each season','Production Fee','that season','claims','multiple seasons','allocated proportionately']::text[], '{"doc": "PSA_Principal_Terms", "section": "Limitation of Liability", "note": "Per-season cap for series", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Per-season cap structure is appropriate for multi-season series deals. Proportionate allocation for multi-season claims is practical approach."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon''s liability is capped at fees paid hereunder. The cap shall increase by the amount of any documented out-of-pocket costs incurred by ProdCo in direct reliance on Amazon''s material breach, up to an additional 50% of the base cap.', ARRAY['Amazon''s liability','capped','fees paid','cap','increase','documented out-of-pocket costs','ProdCo','direct reliance','Amazon''s material breach','additional 50%','base cap']::text[], '{"doc": "Counterparty_Markup", "section": "Limitation of Liability", "note": "Reliance costs addition to cap", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Limited increase for documented reliance costs is reasonable if capped at 50% of base cap. ''Direct reliance'' and ''documented'' requirements limit exposure."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon''s aggregate liability shall not exceed the total fees paid. This cap shall be adjusted annually for inflation using the Consumer Price Index, with adjustments applied on each anniversary of the Effective Date.', ARRAY['Amazon''s aggregate liability','not exceed','total fees','cap','adjusted annually','inflation','Consumer Price Index','adjustments','anniversary','Effective Date']::text[], '{"doc": "Counterparty_Markup", "section": "Limitation of Liability", "note": "Inflation adjustment to cap", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Inflation adjustment is reasonable for long-term deals to preserve real value of cap. CPI is objective standard. Requires Legal review of implementation mechanics."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon''s liability cap equals fees paid. If a claim arises after the initial release of the Program, the cap shall be the greater of (a) fees paid, or (b) an amount equal to six (6) months of Net Receipts attributable to the Program.', ARRAY['Amazon''s liability cap','equals','fees paid','claim arises','after initial release','cap','greater of','fees paid','six months','Net Receipts','attributable','Program']::text[], '{"doc": "Counterparty_Markup", "section": "Limitation of Liability", "note": "Post-release revenue-based cap alternative", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Revenue-based alternative for post-release claims acknowledges ongoing exploitation value. Six-month limitation contains exposure. Requires Legal review."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon''s liability is capped at fees paid. This cap shall apply separately to each distinct breach, such that the aggregate cap for multiple unrelated breaches shall equal the fees paid multiplied by the number of distinct breaches, not to exceed three times (3x) the fees paid in total.', ARRAY['Amazon''s liability','capped','fees paid','cap','apply separately','distinct breach','aggregate cap','multiple','unrelated breaches','multiplied','number of breaches','not to exceed','3x','total']::text[], '{"doc": "Counterparty_Markup", "section": "Limitation of Liability", "note": "Per-breach cap with overall ceiling", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Per-breach cap with 3x overall ceiling provides some additional coverage for multiple distinct issues while maintaining overall limit. Complex to administer but capped."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon''s aggregate liability shall be capped at fees paid. Defense costs incurred by ProdCo in connection with third-party claims arising from Amazon''s breach shall be excluded from the cap and payable by Amazon in addition to capped amounts.', ARRAY['Amazon''s aggregate liability','capped','fees paid','defense costs','ProdCo','third-party claims','Amazon''s breach','excluded from cap','payable','Amazon','addition to','capped amounts']::text[], '{"doc": "Counterparty_Markup", "section": "Limitation of Liability", "note": "Defense costs outside cap", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Defense costs outside cap for third-party claims from Amazon breach is reasonable given Amazon''s indemnification structure. Ensures ProdCo can adequately defend."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon''s liability is capped at the Production Fee. For purposes of calculating the cap, ''Production Fee'' shall include all amounts paid by Amazon to ProdCo under this Agreement, including any bonuses, adjustments, or additional payments.', ARRAY['Amazon''s liability','capped','Production Fee','calculating','cap','Production Fee','include','all amounts paid','Amazon','ProdCo','bonuses','adjustments','additional payments']::text[], '{"doc": "Counterparty_Markup", "section": "Limitation of Liability", "note": "Inclusive cap calculation", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Inclusive definition of Production Fee for cap purposes benefits ProdCo and is fair\u2014cap should relate to total deal value."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon''s liability cap shall equal the total exploitation revenue generated by Amazon from the Program. The cap shall increase as exploitation continues, with no upper limit.', ARRAY['Amazon''s liability cap','equal','total exploitation revenue','generated','Amazon','Program','cap','increase','exploitation continues','no upper limit']::text[], '{"doc": "Counterparty_Markup", "section": "Limitation of Liability", "note": "Revenue-based unlimited cap", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Revenue-based cap with no upper limit creates unlimited, unpredictable exposure. Cap must be fixed or tied to fees paid, not open-ended revenue."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon''s liability shall be capped at fees paid. This cap shall not apply to any claim where ProdCo can demonstrate that the damages suffered exceed the cap amount, in which case Amazon''s liability shall equal actual damages.', ARRAY['Amazon''s liability','capped','fees paid','cap','not apply','claim','ProdCo can demonstrate','damages','exceed','cap amount','Amazon''s liability','equal','actual damages']::text[], '{"doc": "Counterparty_Markup", "section": "Limitation of Liability", "note": "Actual damages exception", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Exception for claims exceeding cap defeats entire purpose of cap. Cap applies precisely to limit exposure when damages are large."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon''s liability is capped at fees paid. However, if Amazon''s breach is determined to be material, the cap shall not apply, and Amazon shall be liable for actual damages without limitation.', ARRAY['Amazon''s liability','capped','fees paid','however','Amazon''s breach','material','cap','not apply','Amazon','liable','actual damages','without limitation']::text[], '{"doc": "Counterparty_Markup", "section": "Limitation of Liability", "note": "Material breach exception to cap", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Material breach exception eliminates cap for exactly the claims it''s meant to address. Material breaches are the high-damage scenarios where cap is most needed."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon''s and ProdCo''s liability caps shall be equivalent. If Amazon''s cap is set at fees paid, ProdCo''s cap shall also be set at fees paid. Any asymmetry in caps shall be prohibited.', ARRAY['Amazon''s','ProdCo''s','liability caps','equivalent','Amazon''s cap','fees paid','ProdCo''s cap','fees paid','asymmetry','caps','prohibited']::text[], '{"doc": "Counterparty_Proposal", "section": "Limitation of Liability", "note": "Forced cap equivalence", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Forced cap equivalence ignores that ProdCo''s content obligations create different risk profile than Amazon''s. Amazon''s cap on ProdCo would limit indemnification recovery."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon''s liability cap shall be the lesser of (a) fees paid, or (b) $100,000. This cap applies to all claims including indemnification claims and payment disputes.', ARRAY['Amazon''s liability cap','lesser of','fees paid','$100,000','cap applies','all claims','including','indemnification','payment disputes']::text[], '{"doc": "Counterparty_Markup", "section": "Limitation of Liability", "note": "Low-dollar cap including payments", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "$100K cap including payment disputes would allow Amazon to limit payment obligations. Cap must exclude payments and should be reasonable relative to deal size."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon''s liability is uncapped and unlimited. The parties agree that liability caps are inappropriate given the collaborative nature of this production relationship and the significant investment made by ProdCo.', ARRAY['Amazon''s liability','uncapped','unlimited','liability caps','inappropriate','collaborative nature','production relationship','significant investment','ProdCo']::text[], '{"doc": "Counterparty_Proposal", "section": "Limitation of Liability", "note": "No cap on Amazon liability", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Uncapped Amazon liability creates unlimited exposure. Amazon requires liability cap as fundamental commercial protection regardless of relationship characterization."}'::jsonb)
